import { useEffect, useMemo, useState } from 'react';
import {
  BrowserRouter, Navigate, Outlet, Route, Routes,
  useLocation,
} from 'react-router-dom';
import { Toaster } from 'react-hot-toast';

import Home from './pages/customer/Home.jsx';
import Services from './pages/customer/Services.jsx';
import MyBookings from './pages/customer/MyBookings.jsx';
import Contact from './pages/customer/Contact.jsx';
import Profile from './pages/customer/Profile.jsx';
import PaymentSuccess from './pages/customer/PaymentSuccess.jsx';
import PaymentFailure from './pages/customer/PaymentFailure.jsx';
import PaymentHistory from './pages/customer/PaymentHistory.jsx';

import Login from './pages/Login.jsx';
import Register from './pages/Register.jsx';
import ForgotPassword from './pages/ForgotPassword.jsx';
import ResetPassword from './pages/ResetPassword.jsx';

import AdminLayout from './components/admin/common/layout/AdminLayout.jsx';
import Overview from './pages/admin/Overview.jsx';
import AllJobs from './pages/admin/AllJobs.jsx';
import AllTechnicians from './pages/admin/AllTeachnicians.jsx';
import HireTechnician from './pages/admin/HireTechnician.jsx';
import Messages from './pages/admin/Messages.jsx';
import Revenue from './pages/admin/Revenue.jsx';
import Payments from './pages/admin/Payments.jsx';
import Settings from './pages/admin/Settings.jsx';
import TechnicianDashboard from './pages/technician/Dashboard.jsx';

import Navbar from './components/customer/Navbar.jsx';
import Footer from './components/customer/Footer.jsx';
import BookingModal from './components/customer/BookingModal.jsx';
import { connectSocket, disconnectSocket } from './services/socket';

const getStoredUser = () => {
  try { return JSON.parse(localStorage.getItem('user') || 'null'); }
  catch { return null; }
};

const getRoleHome = (role) => {
  if (role === 'admin') return '/admin/dashboard';
  if (role === 'technician') return '/technician/dashboard';
  return '/';
};

const useAuth = () => {
  const readAuth = () => {
    const token = localStorage.getItem('token');
    const user = getStoredUser();
    return { token, user, isLoggedIn: Boolean(token && user) };
  };
  const [auth, setAuth] = useState(readAuth);

  useEffect(() => {
    const sessionKey = 'fixly_session_active';
    if (!sessionStorage.getItem(sessionKey)) {
      localStorage.removeItem('token');
      localStorage.removeItem('user');
      sessionStorage.setItem(sessionKey, '1');
      setAuth({ token: null, user: null, isLoggedIn: false });
    }
    const syncAuth = () => setAuth(readAuth());
    window.addEventListener('storage', syncAuth);
    window.addEventListener('focus', syncAuth);
    window.addEventListener('auth-changed', syncAuth);
    return () => {
      window.removeEventListener('storage', syncAuth);
      window.removeEventListener('focus', syncAuth);
      window.removeEventListener('auth-changed', syncAuth);
    };
  }, []);

  const logout = () => {
    localStorage.removeItem('token');
    localStorage.removeItem('user');
    setAuth({ token: null, user: null, isLoggedIn: false });
  };

  return { ...auth, logout, refreshAuth: () => setAuth(readAuth()) };
};

// RootRoute is removed as the path "/" is now handled inside PublicLayout
const RootRoute = ({ auth }) => {
  const liveUser = getStoredUser() || auth?.user;
  if (liveUser?.role) return <Navigate to={getRoleHome(liveUser.role)} replace />;
  return <Navigate to="/" replace />;
};

const CustomerOrPublicRoute = ({ children, auth }) => {
  const liveUser = getStoredUser() || auth?.user;
  if (liveUser?.role && liveUser.role !== 'customer')
    return <Navigate to={getRoleHome(liveUser.role)} replace />;
  return children;
};

const ProtectedRoute = ({ allowedRoles, children, auth }) => {
  const location = useLocation();
  const liveToken = localStorage.getItem('token') || auth?.token;
  const liveUser = getStoredUser() || auth?.user;
  if (!liveToken || !liveUser) return <Navigate to="/login" replace state={{ from: location }} />;
  if (allowedRoles && !allowedRoles.includes(liveUser.role))
    return <Navigate to={getRoleHome(liveUser.role)} replace />;
  return children;
};

const CustomerProtectedRoute = ({ children, auth }) => {
  const location = useLocation();
  const liveToken = localStorage.getItem('token') || auth?.token;
  const liveUser = getStoredUser() || auth?.user;
  if (!liveToken || !liveUser) return <Navigate to="/login" replace state={{ from: location }} />;
  if (liveUser.role !== 'customer') return <Navigate to={getRoleHome(liveUser.role)} replace />;
  return children;
};

// With Navbar + Footer
const PublicLayout = ({ onServiceClick }) => (
  <div className="min-h-screen flex flex-col bg-gray-50">
    <Navbar />
    <main className="flex-1"><Outlet context={{ onServiceClick }} /></main>
    <Footer />
  </div>
);

function App() {
  const auth = useAuth();
  const [isBookingModalOpen, setIsBookingModalOpen] = useState(false);
  const [selectedService, setSelectedService] = useState(null);

  const handleServiceClick = (service) => {
    setSelectedService(service);
    setIsBookingModalOpen(true);
  };

  const modalService = useMemo(() => selectedService || null, [selectedService]);

  useEffect(() => {
    if (auth?.token) {
      connectSocket(auth.token);
    } else {
      disconnectSocket();
    }
    return () => disconnectSocket();
  }, [auth?.token]);

  return (
    <BrowserRouter>
      <Routes>
        {/* Route path="/" element={<RootRoute auth={auth} />} /> */}

        {/* Redirect /home to / */}
        <Route path="/home" element={<Navigate to="/" replace />} />

        {/* Customer pages — with Navbar + Footer */}
        <Route element={<PublicLayout onServiceClick={handleServiceClick} />}>
          <Route path="/" element={
            <CustomerOrPublicRoute auth={auth}>
              <Home onServiceClick={handleServiceClick} />
            </CustomerOrPublicRoute>
          } />
          <Route path="/services" element={
            <CustomerOrPublicRoute auth={auth}>
              <Services onServiceClick={handleServiceClick} />
            </CustomerOrPublicRoute>
          } />
          <Route path="/contact" element={
            <CustomerOrPublicRoute auth={auth}>
              <Contact />
            </CustomerOrPublicRoute>
          } />
          <Route path="/my-bookings" element={
            <CustomerProtectedRoute auth={auth}>
              <MyBookings />
            </CustomerProtectedRoute>
          } />
          <Route path="/profile" element={
            <CustomerProtectedRoute auth={auth}>
              <Profile />
            </CustomerProtectedRoute>
          } />
          <Route path="/payment-history" element={
            <CustomerProtectedRoute auth={auth}>
              <PaymentHistory />
            </CustomerProtectedRoute>
          } />
          <Route path="/payment/success" element={
            <CustomerProtectedRoute auth={auth}>
              <PaymentSuccess />
            </CustomerProtectedRoute>
          } />
          <Route path="/payment/failure" element={
            <CustomerProtectedRoute auth={auth}>
              <PaymentFailure />
            </CustomerProtectedRoute>
          } />
        </Route>

        {/* Auth */}
        <Route path="/login" element={<Login />} />
        <Route path="/register" element={<Register />} />
        <Route path="/forgot-password" element={<ForgotPassword />} />
        <Route path="/reset-password" element={<ResetPassword />} />

        {/* Admin */}
        <Route path="/admin" element={
          <ProtectedRoute allowedRoles={['admin']} auth={auth}>
            <AdminLayout />
          </ProtectedRoute>
        }>
          <Route index element={<Navigate to="dashboard" replace />} />
          <Route path="dashboard" element={<Overview />} />
          <Route path="jobs" element={<AllJobs />} />
          <Route path="technicians" element={<AllTechnicians />} />
          <Route path="hire" element={<HireTechnician />} />
          <Route path="messages" element={<Messages />} />
          <Route path="revenue" element={<Revenue />} />
          <Route path="payments" element={<Payments />} />
          <Route path="settings" element={<Settings />} />
        </Route>

        {/* Technician */}
        <Route path="/technician/dashboard" element={
          <ProtectedRoute allowedRoles={['technician']} auth={auth}>
            <TechnicianDashboard />
          </ProtectedRoute>
        } />

        <Route path="*" element={<Navigate to="/" replace />} />
      </Routes>

      <BookingModal
        isOpen={isBookingModalOpen}
        service={modalService}
        onClose={() => setIsBookingModalOpen(false)}
        onSuccess={() => {}}
      />

      <Toaster position="top-right" toastOptions={{ duration: 2500 }} />
    </BrowserRouter>
  );
}

export default App;

import { IcJobs, IcEarnings, IcProfile, IcChat } from "./Icons";

export default function BottomNav({ active, onChange, chatUnread = 0 }) {
  const items = [
    { id: "jobs",     label: "Jobs",     Icon: IcJobs },
    { id: "chat",     label: "Messages", Icon: IcChat,     badge: chatUnread },
    { id: "earnings", label: "Earnings", Icon: IcEarnings },
    { id: "profile",  label: "Profile",  Icon: IcProfile },
  ];
  return (
    <nav className="flex h-16 flex-shrink-0 bg-[rgba(15,8,42,0.95)] backdrop-blur-xl border-t border-white/10">
      {items.map(({ id, label, Icon, badge }) => {
        const on = active === id;
        return (
          <button key={id} onClick={() => onChange(id)}
            className={`flex-1 flex flex-col items-center justify-center gap-1 border-none bg-transparent cursor-pointer text-[10px] font-semibold font-jakarta transition-colors duration-200 relative ${on ? "text-orange" : "text-white/40"}`}>
            <span className="relative">
              <Icon size={20} />
              {badge > 0 && (
                <span className="absolute -top-1 -right-1.5 w-4 h-4 bg-orange text-white text-[8px] font-bold rounded-full flex items-center justify-center">
                  {badge > 9 ? "9+" : badge}
                </span>
              )}
            </span>
            {label}
          </button>
        );
      })}
    </nav>
  );
}

import Avatar from "./Avatar";
import { IcBell, IcLogout } from "./Icons";

export default function Header({ user, unreadCount, onNotif, onLogout, onAvatarClick }) {
  return (
    <header className="flex items-center justify-between px-5 py-3 bg-black/[0.28] backdrop-blur-xl border-b border-white/[0.13] flex-shrink-0 z-10 relative">
      <div className="flex items-center gap-3">
        <Avatar user={user} size="sm" onClick={onAvatarClick} />
        <span className="font-bold text-[15px] text-white">Hi {user?.name?.split(" ")[0]}</span>
      </div>
      <div className="flex items-center gap-3">
        <button onClick={onNotif} className="relative p-1.5 bg-transparent border-none cursor-pointer text-white">
          <IcBell />
          {unreadCount > 0 && (
            <span className="absolute top-0.5 right-0.5 w-4 h-4 bg-orange text-white text-[9px] font-bold rounded-full flex items-center justify-center">
              {unreadCount > 9 ? "9+" : unreadCount}
            </span>
          )}
        </button>
        <button onClick={onLogout} className="flex items-center gap-1.5 px-3.5 py-1.5 bg-white/[0.13] border border-white/[0.22] text-white text-[13px] font-semibold rounded-xl cursor-pointer hover:bg-white/20 transition-colors">
          <IcLogout /> Logout
        </button>
      </div>
    </header>
  );
}

