import { IcMapPin } from "./Icons";

export default function MapBox({ label = "Tap to navigate", onClick }) {
  return (
    <div
      onClick={onClick}
      className="bg-white/[0.06] border border-white/10 rounded-xl h-28 flex flex-col items-center justify-center gap-2 cursor-pointer my-4 hover:bg-white/10 active:scale-[0.98] transition-all"
    >
      <IcMapPin />
      <span className="text-xs text-white/50 text-center px-4">{label}</span>
    </div>
  );
}

import { IcBell, IcClose } from "./Icons";
import { timeAgo } from "../utils/helpers";

const DOT = { success:"bg-green-500", info:"bg-blue-500", warning:"bg-yellow-500", error:"bg-red-500" };

export default function NotificationPanel({ notifications, loading, onClose, onMarkAll, onDelete }) {
  return (
    <div className="fixed top-16 right-3 w-80 max-h-[420px] bg-notif-dark border border-white/[0.13] rounded-2xl z-[200] shadow-2xl flex flex-col overflow-hidden animate-fade-in">
      {/* Header */}
      <div className="flex items-center justify-between px-5 py-3.5 border-b border-white/10">
        <div className="flex items-center gap-2 text-[15px] font-bold text-white">
          <IcBell size={16}/> Notifications
        </div>
        <button onClick={onClose} className="bg-transparent border-none text-white/50 cursor-pointer flex hover:text-white/80 transition-colors">
          <IcClose size={18}/>
        </button>
      </div>

      {/* List */}
      <div className="overflow-y-auto flex-1">
        {loading ? (
          [1,2,3].map(i=>(
            <div key={i} className="px-4 py-3 border-b border-white/[0.06]">
              <div className="h-3 w-24 bg-white/10 rounded animate-pulse mb-2"/>
              <div className="h-2.5 w-48 bg-white/10 rounded animate-pulse"/>
            </div>
          ))
        ) : notifications.length === 0 ? (
          <p className="p-5 text-center text-white/40 text-[13px]">No notifications</p>
        ) : notifications.map((n) => (
          <div key={n._id || n.id} className={`px-4 py-3 border-b border-white/[0.06] group relative ${!n.read?"bg-orange/[0.07]":""}`}>
            <div className="flex items-center gap-2 mb-1">
              <div className={`w-2 h-2 rounded-full flex-shrink-0 ${DOT[n.type]||"bg-gray-400"}`}/>
              <span className="text-[13px] font-bold text-white">{n.title}</span>
            </div>
            <p className="text-xs text-white/60 pl-4 mt-0.5">{n.body || n.desc}</p>
            <p className="text-[11px] text-white/35 pl-4 mt-1">{timeAgo(n.createdAt) || n.time}</p>
            {onDelete && (
              <button
                onClick={() => onDelete(n._id || n.id)}
                className="absolute top-2 right-2 opacity-0 group-hover:opacity-100 text-white/30 hover:text-white/70 bg-transparent border-none cursor-pointer text-xs transition-opacity"
              >✕</button>
            )}
          </div>
        ))}
      </div>

      {/* Footer */}
      <div onClick={onMarkAll} className="p-3 text-center border-t border-white/[0.08] cursor-pointer text-orange text-[13px] font-semibold hover:bg-orange/[0.08] transition-colors">
        Mark all as read
      </div>
    </div>
  );
}

﻿import { useState, useEffect, useRef } from 'react';
import { Bell, X, CheckCircle, AlertCircle, Users, Briefcase, DollarSign, Lock, User, XCircle, Shuffle } from 'lucide-react';
import { adminAPI } from '../../../services/api';

const NotificationsDropdown = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [notifications, setNotifications] = useState([]);
  const [unreadCount, setUnreadCount] = useState(0);
  const [loading, setLoading] = useState(false);
  const isFetchingRef = useRef(false);

  const getNotificationIcon = (type) => {
    const iconMap = {
      profile_updated: User,
      password_changed: Lock,
      job_created: Briefcase,
      job_accepted: CheckCircle,
      job_in_progress: Briefcase,
      job_completed: CheckCircle,
      job_cancelled: XCircle,
      job_reassigned: Shuffle,
      technician_hired: Users,
      technician_activated: CheckCircle,
      technician_deactivated: AlertCircle,
      payment_received: DollarSign,
      payment_failed: AlertCircle,
      new_review: CheckCircle,
    };
    return iconMap[type] || Bell;
  };

  const getNotificationColor = (type) => {
    const colorMap = {
      profile_updated: 'green',
      password_changed: 'yellow',
      job_created: 'blue',
      job_accepted: 'green',
      job_in_progress: 'blue',
      job_completed: 'green',
      job_cancelled: 'red',
      job_reassigned: 'blue',
      technician_hired: 'green',
      technician_activated: 'green',
      technician_deactivated: 'red',
      payment_received: 'green',
      payment_failed: 'red',
      new_review: 'yellow',
    };
    return colorMap[type] || 'blue';
  };

  const formatTime = (createdAt) => {
    const notifDate = new Date(createdAt);
    const now = new Date();
    const diffMs = now - notifDate;
    const diffMins = Math.floor(diffMs / 60000);
    const diffHours = Math.floor(diffMs / 3600000);
    const diffDays = Math.floor(diffMs / 86400000);

    if (diffMins < 1) return 'Just now';
    if (diffMins < 60) return `${diffMins} minute${diffMins > 1 ? 's' : ''} ago`;
    if (diffHours < 24) return `${diffHours} hour${diffHours > 1 ? 's' : ''} ago`;
    if (diffDays < 7) return `${diffDays} day${diffDays > 1 ? 's' : ''} ago`;
    
    return notifDate.toLocaleDateString();
  };

  const fetchNotifications = async (silent = false) => {
    if (isFetchingRef.current) return;
    isFetchingRef.current = true;
    try {
      if (!silent) setLoading(true);
      const response = await adminAPI.getNotifications(20);
      
      if (response.data.success) {
        const notifs = response.data.data || [];
        setNotifications(notifs);
        setUnreadCount(notifs.filter(n => !n.is_read).length);
        console.log('✅ Fetched', notifs.length, 'notifications');
      }
    } catch (error) {
      console.error('❌ Error fetching notifications:', error);
    } finally {
      if (!silent) setLoading(false);
      isFetchingRef.current = false;
    }
  };

  useEffect(() => {
    fetchNotifications();
    
    // Faster refresh so new notifications appear sooner.
    const interval = setInterval(() => fetchNotifications(true), 10000);
    return () => clearInterval(interval);
  }, []);

  useEffect(() => {
    if (isOpen) {
      fetchNotifications();
    }
  }, [isOpen]);

  useEffect(() => {
    const handleWindowFocus = () => fetchNotifications(true);
    window.addEventListener('focus', handleWindowFocus);
    return () => window.removeEventListener('focus', handleWindowFocus);
  }, []);

  const markAsRead = async (id) => {
    try {
      await adminAPI.markNotificationRead(id);
      setNotifications(prev => 
        prev.map(notif => 
          notif.id === id ? { ...notif, is_read: true } : notif
        )
      );
      setUnreadCount(prev => Math.max(0, prev - 1));
    } catch (error) {
      console.error('Error marking notification as read:', error);
    }
  };

  const markAllAsRead = async () => {
    try {
      await adminAPI.markAllNotificationsRead();
      setNotifications(prev => prev.map(n => ({ ...n, is_read: true })));
      setUnreadCount(0);
    } catch (error) {
      console.error('Error marking all notifications as read:', error);
    }
  };

  const clearAll = () => {
    setNotifications([]);
    setUnreadCount(0);
    setIsOpen(false);
  };

  const getIconColor = (color) => {
    const colors = {
      blue: 'text-blue-400 bg-blue-500/20',
      green: 'text-green-400 bg-green-500/20',
      purple: 'text-blue-400 bg-blue-500/20',
      orange: 'text-amber-300 bg-amber-500/20',
      red: 'text-red-400 bg-red-500/20',
      yellow: 'text-yellow-400 bg-yellow-500/20'
    };
    return colors[color] || colors.blue;
  };

  // Close dropdown when clicking outside
  useEffect(() => {
    const handleClickOutside = (event) => {
      if (isOpen && !event.target.closest('.notifications-dropdown')) {
        setIsOpen(false);
      }
    };

    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, [isOpen]);

  return (
    <div className="relative notifications-dropdown">
      {/* Bell Icon Button */}
      <button
        onClick={() => setIsOpen(!isOpen)}
        className="relative p-2 rounded-lg hover:bg-gray-100 transition-colors"
      >
        <Bell size={20} className="text-gray-700" />
        {unreadCount > 0 && (
          <span className="absolute top-1 right-1 w-5 h-5 bg-amber-500 rounded-full flex items-center justify-center text-slate-900 text-xs font-bold">
            {unreadCount}
          </span>
        )}
      </button>

      {/* Dropdown Panel */}
      {isOpen && (
        <>
          {/* Dropdown */}
          <div className="absolute right-0 mt-2 w-96 bg-white rounded-lg shadow-xl border border-gray-200 z-[9999] max-h-[600px] flex flex-col">
            {/* Header */}
            <div className="p-4 border-b border-gray-200 flex items-center justify-between">
              <div>
                <h3 className="text-gray-800 font-bold text-lg">Notifications</h3>
                <p className="text-gray-700 text-sm font-medium">{unreadCount} unread</p>
              </div>
              <button
                onClick={() => setIsOpen(false)}
                className="text-gray-700 hover:text-gray-900 transition-colors"
              >
                <X size={20} />
              </button>
            </div>

            {/* Actions */}
            {notifications.length > 0 && (
              <div className="px-4 py-2 border-b border-gray-200 flex gap-2">
                <button
                  onClick={markAllAsRead}
                  className="text-xs text-blue-700 hover:text-blue-800 font-medium"
                >
                  Mark all as read
                </button>
                <span className="text-gray-600">•</span>
                <button
                  onClick={clearAll}
                  className="text-sm text-gray-700 hover:text-gray-900 font-medium"
                >
                  Clear all
                </button>
              </div>
            )}

            {/* Notifications List */}
            <div className="overflow-y-auto flex-1">
              {loading && (
                <div className="p-8 text-center">
                  <Bell size={48} className="mx-auto text-gray-300 mb-3 animate-pulse" />
                  <p className="text-gray-700 text-sm font-medium">Loading...</p>
                </div>
              )}
              
              {!loading && notifications.length === 0 ? (
                <div className="p-8 text-center">
                  <Bell size={48} className="mx-auto text-gray-300 mb-3" />
                  <p className="text-gray-700 text-sm font-medium">No notifications</p>
                  <p className="text-gray-600 text-sm mt-1">You're all caught up!</p>
                </div>
              ) : (
                <div className="divide-y divide-gray-100">
                  {notifications.map((notif) => {
                    const Icon = getNotificationIcon(notif.type);
                    const color = getNotificationColor(notif.type);
                    return (
                      <div
                        key={notif.id}
                        onClick={() => !notif.is_read && markAsRead(notif.id)}
                        className={`p-4 hover:bg-gray-50 transition-colors cursor-pointer ${
                          !notif.is_read ? 'bg-blue-50/40' : ''
                        }`}
                      >
                        <div className="flex gap-3">
                          {/* Icon */}
                          <div className={`w-10 h-10 rounded-full flex items-center justify-center flex-shrink-0 ${getIconColor(color)}`}>
                            <Icon size={20} />
                          </div>

                          {/* Content */}
                          <div className="flex-1 min-w-0">
                            <div className="flex items-start justify-between gap-2">
                              <h4 className="text-gray-800 font-medium text-sm">{notif.title}</h4>
                              {!notif.is_read && (
                                <div className="w-2 h-2 bg-amber-400 rounded-full flex-shrink-0 mt-1" />
                              )}
                            </div>
                            <p className="text-gray-700 text-sm mt-1">{notif.message}</p>
                            <p className="text-gray-700 text-sm mt-2">{formatTime(notif.created_at)}</p>
                          </div>
                        </div>
                      </div>
                    );
                  })}
                </div>
              )}
            </div>

            {/* Footer */}
            {notifications.length > 0 && (
              <div className="p-3 border-t border-gray-200 text-center">
                <button 
                  onClick={async () => {
                    await fetchNotifications();
                    setIsOpen(false);
                  }}
                  disabled={loading}
                  className="text-blue-700 hover:text-blue-800 text-sm font-medium disabled:opacity-50"
                >
                  {loading ? 'Refreshing...' : 'Refresh Notifications'}
                </button>
              </div>
            )}
          </div>
        </>
      )}
    </div>
  );
};

export default NotificationsDropdown;

import { useState, useEffect } from 'react';
import { X, UserCheck } from 'lucide-react';
import { adminAPI } from '../../../services/api';

const ReassignTechnicianModal = ({ job, isOpen, onClose, onSuccess }) => {
  const [technicians, setTechnicians] = useState([]);
  const [selectedTechnician, setSelectedTechnician] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  useEffect(() => {
    if (isOpen) {
      setSelectedTechnician('');
      setError('');
      fetchTechnicians();
    }
  }, [isOpen, job?.technician?.id]);

  const fetchTechnicians = async () => {
    try {
      const response = await adminAPI.getAllTechnicians();
      if (response.data.success) {
        // Filter active technicians
        const activeTechs = response.data.data.filter((tech) =>
          tech.is_active && Number(tech.id) !== Number(job?.technician?.id)
        );
        setTechnicians(activeTechs);
      }
    } catch (err) {
      console.error('Error fetching technicians:', err);
    }
  };

  const handleReassign = async () => {
    if (!selectedTechnician) {
      setError('Please select a technician');
      return;
    }

    setLoading(true);
    setError('');

    try {
      // Update booking with new technician
      const response = await adminAPI.updateBooking(job.id, {
        technician_id: parseInt(selectedTechnician)
      });

      if (response.data.success) {
        onSuccess();
        onClose();
      }
    } catch (err) {
      setError(err.response?.data?.message || 'Failed to reassign technician');
    } finally {
      setLoading(false);
    }
  };

  if (!isOpen) return null;

  return (
    <>
      {/* Backdrop */}
      <div 
        className="fixed inset-0 bg-black/50 backdrop-blur-sm z-50"
        onClick={onClose}
      />

      {/* Modal */}
      <div className="fixed inset-0 flex items-center justify-center z-50 p-4">
        <div className="bg-white w-full max-w-md p-6 relative rounded-xl border border-gray-200 shadow-xl">
          {/* Close Button */}
          <button
            onClick={onClose}
            className="absolute top-4 right-4 text-gray-700 hover:text-gray-900 transition-colors"
          >
            <X size={20} />
          </button>

          {/* Header */}
          <div className="mb-6">
            <h2 className="text-2xl font-bold text-blue-700 mb-2">Reassign Technician</h2>
            <p className="text-gray-700 text-sm">
              Job #{job?.id} - {job?.service?.name}
            </p>
            {job?.technician && (
              <p className="text-gray-700 text-sm mt-1">
                Current: {job.technician.name}
              </p>
            )}
          </div>

          {/* Error Message */}
          {error && (
            <div className="bg-red-50 border border-red-200 rounded-lg p-3 mb-4">
              <p className="text-red-700 text-sm">{error}</p>
            </div>
          )}

          {/* Technician Selection */}
          <div className="mb-6">
            <label className="block text-gray-700 text-sm font-medium mb-3">
              Select New Technician
            </label>
            
            <div className="space-y-2 max-h-96 overflow-y-auto">
              {technicians.length === 0 ? (
                <p className="text-gray-700 text-sm text-center py-4 font-medium">
                  No available technicians
                </p>
              ) : (
                technicians.map((tech) => (
                  <label
                    key={tech.id}
                    className={`flex items-center gap-3 p-3 rounded-lg border-2 cursor-pointer transition-all ${
                      selectedTechnician === tech.id.toString()
                        ? 'border-blue-400 bg-blue-500/10'
                        : 'border-gray-200 hover:border-blue-300 hover:bg-blue-50'
                    }`}
                  >
                    <input
                      type="radio"
                      name="technician"
                      value={tech.id}
                      checked={selectedTechnician === tech.id.toString()}
                      onChange={(e) => setSelectedTechnician(e.target.value)}
                      className="w-4 h-4 text-blue-500"
                    />
                    
                    <div className="w-10 h-10 rounded-full bg-gradient-to-br from-blue-500 to-cyan-500 flex items-center justify-center text-white font-bold flex-shrink-0">
                      {tech.name.charAt(0)}
                    </div>
                    
                    <div className="flex-1 min-w-0">
                      <p className="text-gray-800 font-medium">{tech.name}</p>
                      <div className="flex flex-wrap gap-1 mt-1">
                        {tech.services?.map((service) => (
                          <span 
                            key={service.id}
                            className="text-xs text-blue-700"
                          >
                            {service.name}
                          </span>
                        )) || <span className="text-gray-700 text-sm">No services</span>}
                      </div>
                      <div className="flex gap-3 mt-1 text-sm text-gray-700">
                        <span>{tech.total_jobs || 0} jobs</span>
                        <span>★ {tech.rating || '0.0'}</span>
                      </div>
                    </div>
                  </label>
                ))
              )}
            </div>
          </div>

          {/* Actions */}
          <div className="flex gap-3">
            <button
              onClick={onClose}
              className="flex-1 px-4 py-3 bg-red-600 hover:bg-red-700 text-white rounded-lg transition-colors"
            >
              Cancel
            </button>
            <button
              onClick={handleReassign}
              disabled={loading || !selectedTechnician}
              className="flex-1 btn-primary disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-2"
            >
              {loading ? (
                'Reassigning...'
              ) : (
                <>
                  <UserCheck size={18} />
                  Reassign
                </>
              )}
            </button>
          </div>
        </div>
      </div>
    </>
  );
};

