import { useState, useEffect, useRef } from 'react';
import { Link, useLocation, useNavigate } from 'react-router-dom';
import { User, LogOut, ChevronDown, Menu, X, BookOpen, Settings, DollarSign } from 'lucide-react';
import { toast } from 'react-hot-toast';
import NotificationsDropdown from '../../pages/customer/NotificationsDropdown';
import { getImageUrl } from '../../utils/imageHelper';

const Navbar = () => {
  const location = useLocation();
  const navigate = useNavigate();
  const dropdownRef = useRef(null);

  const [user, setUser] = useState(null);
  const [showDropdown, setShowDropdown] = useState(false);
  const [mobileOpen, setMobileOpen] = useState(false);

  useEffect(() => {
    const stored = localStorage.getItem('user');
    if (stored) {
      try { setUser(JSON.parse(stored)); }
      catch { setUser(null); }
    } else {
      setUser(null);
    }
  }, [location.pathname]);

  useEffect(() => {
    const handler = (e) => {
      if (dropdownRef.current && !dropdownRef.current.contains(e.target)) {
        setShowDropdown(false);
      }
    };
    document.addEventListener('mousedown', handler);
    return () => document.removeEventListener('mousedown', handler);
  }, []);

  const handleLogout = () => {
    localStorage.removeItem('token');
    localStorage.removeItem('user');
    setUser(null);
    setShowDropdown(false);
    toast.success('Logged out successfully');
    navigate('/');
  };

  const isActive = (path) =>
    location.pathname === path
      ? 'text-blue-600 font-bold border-b-2 border-blue-600'
      : 'text-gray-700 hover:text-blue-600';

  const navLinks = [
    { to: '/', label: 'Home' },
    { to: '/services', label: 'Services' },
    { to: '/my-bookings', label: 'My Bookings' },
    ...(user?.role === 'customer' ? [{ to: '/payment-history', label: 'Payments' }] : []),
    { to: '/contact', label: 'Contact' },
  ];

  const logoTarget = user?.role === 'customer' ? '/home' : '/';

  return (
    <nav className="bg-white shadow-md fixed w-full top-0 left-0 z-50">
      <div className="container mx-auto px-4 py-3 flex justify-between items-center">
        {/* Logo */}
        <Link to={logoTarget} className="flex items-center gap-2">
          <img src="/fixly-logo.jpeg" alt="Fixly" className="w-9 h-9 object-contain rounded-lg" />
          <span className="text-2xl font-bold text-blue-600">Fixly</span>
        </Link>

        {/* Desktop Nav Links */}
        <div className="hidden md:flex items-center gap-8">
          {navLinks.map((link) => (
            <Link
              key={link.to}
              to={link.to}
              className={`transition font-medium text-sm pb-1 ${isActive(link.to)}`}
            >
              {link.label}
            </Link>
          ))}
        </div>

        {/* Right Section */}
        <div className="hidden md:flex items-center gap-2">
          {user ? (
            <>
              {/* Notifications Bell */}
              <NotificationsDropdown />

              {/* User Dropdown */}
              <div className="relative" ref={dropdownRef}>
                <button
                  onClick={() => setShowDropdown(!showDropdown)}
                  className="flex items-center gap-2 bg-blue-50 hover:bg-blue-100 px-3 py-2 rounded-full transition ml-1"
                >
                  {/* Avatar */}
                  <div className="w-8 h-8 rounded-full bg-blue-600 flex items-center justify-center text-white font-bold text-sm overflow-hidden flex-shrink-0">
                    {user.profile_image ? (
                      <img
                        src={getImageUrl(user.profile_image)}
                        alt={user.name}
                        className="w-full h-full object-cover"
                      />
                    ) : (
                      <span>{user.name?.charAt(0).toUpperCase() || 'U'}</span>
                    )}
                  </div>
                  <span className="text-gray-800 font-semibold text-sm max-w-[100px] truncate">
                    {user.name}
                  </span>
                  <ChevronDown size={14} className="text-gray-500" />
                </button>

                {showDropdown && (
                  <div className="absolute right-0 mt-2 w-56 bg-white rounded-xl shadow-lg border border-gray-100 py-2 z-[9999]">
                    {/* User Info */}
                    <div className="px-4 py-3 border-b border-gray-100">
                      <p className="text-gray-800 font-bold text-sm truncate">{user.name}</p>
                      <p className="text-gray-500 text-xs truncate">{user.email}</p>
                    </div>

                    {/* My Bookings */}
                    <Link
                      to="/my-bookings"
                      onClick={() => setShowDropdown(false)}
                      className="flex items-center gap-3 px-4 py-2.5 text-gray-700 hover:bg-blue-50 hover:text-blue-600 transition text-sm"
                    >
                      <BookOpen size={16} />
                      My Bookings
                    </Link>

                    {/* My Profile */}
                    <Link
                      to="/payment-history"
                      onClick={() => setShowDropdown(false)}
                      className="flex items-center gap-3 px-4 py-2.5 text-gray-700 hover:bg-blue-50 hover:text-blue-600 transition text-sm"
                    >
                      <DollarSign size={16} />
                      Payment History
                    </Link>

                    <Link
                      to="/profile"
                      onClick={() => setShowDropdown(false)}
                      className="flex items-center gap-3 px-4 py-2.5 text-gray-700 hover:bg-blue-50 hover:text-blue-600 transition text-sm"
                    >
                      <Settings size={16} />
                      My Profile
                    </Link>

                    <div className="border-t border-gray-100 my-1" />

                    {/* Logout */}
                    <button
                      onClick={handleLogout}
                      className="w-full flex items-center gap-3 px-4 py-2.5 text-red-500 hover:bg-red-50 transition text-sm"
                    >
                      <LogOut size={16} />
                      Logout
                    </button>
                  </div>
                )}
              </div>
            </>
          ) : (
            <div className="flex items-center gap-3">
              <Link
                to="/login"
                className="text-blue-600 font-semibold hover:underline text-sm"
              >
                Login
              </Link>
              <Link
                to="/register"
                className="bg-blue-600 text-white px-5 py-2 rounded-full hover:bg-blue-700 transition font-semibold text-sm"
              >
                Register
              </Link>
            </div>
          )}
        </div>

        {/* Mobile Toggle */}
        <button
          className="md:hidden text-gray-700 p-2"
          onClick={() => setMobileOpen(!mobileOpen)}
        >
          {mobileOpen ? <X size={24} /> : <Menu size={24} />}
        </button>
      </div>

      {/* Mobile Menu */}
      {mobileOpen && (
        <div className="md:hidden bg-white border-t border-gray-100 px-4 py-4 space-y-2">
          {navLinks.map((link) => (
            <Link
              key={link.to}
              to={link.to}
              onClick={() => setMobileOpen(false)}
              className={`block py-2 font-medium transition ${isActive(link.to)}`}
            >
              {link.label}
            </Link>
          ))}
          <div className="border-t border-gray-100 pt-3">
            {user ? (
              <>
                <p className="text-gray-600 text-sm mb-3">
                  Logged in as <strong>{user.name}</strong>
                </p>
                <Link
                  to="/payment-history"
                  onClick={() => setMobileOpen(false)}
                  className="block py-2 text-gray-700 font-medium"
                >
                  Payment History
                </Link>
                <Link
                  to="/profile"
                  onClick={() => setMobileOpen(false)}
                  className="block py-2 text-gray-700 font-medium"
                >
                  My Profile
                </Link>
                <button
                  onClick={() => { handleLogout(); setMobileOpen(false); }}
                  className="w-full text-left text-red-500 font-semibold py-2"
                >
                  Logout
                </button>
              </>
            ) : (
              <div className="flex gap-3">
                <Link
                  to="/login"
                  onClick={() => setMobileOpen(false)}
                  className="flex-1 text-center border border-blue-600 text-blue-600 py-2 rounded-lg font-semibold"
                >
                  Login
                </Link>
                <Link
                  to="/register"
                  onClick={() => setMobileOpen(false)}
                  className="flex-1 text-center bg-blue-600 text-white py-2 rounded-lg font-semibold"
                >
                  Register
                </Link>
              </div>
            )}
          </div>
        </div>
      )}
    </nav>
  );
};

export default Navbar;

import { CalendarDays, ClipboardList, MapPinned, Phone, User, Wallet, X } from 'lucide-react';

const formatDateLabel = (bookingDate, bookingTime) => {
  const raw = `${bookingDate || ''} ${bookingTime || ''}`.trim();
  if (!raw) return 'Schedule not available';
  const d = new Date(raw);
  if (Number.isNaN(d.getTime())) return raw;

  return d.toLocaleString(undefined, {
    year: 'numeric',
    month: 'short',
    day: 'numeric',
    hour: '2-digit',
    minute: '2-digit',
  });
};

const formatNpr = (amount) => `Rs ${Number(amount || 0).toFixed(2)}`;

export default function AcceptedModal({ job, onNavigate, onClose }) {
  const customer = job?.customer || {};
  const location = job?.location?.address || job?.location || customer?.address || 'Not available';
  const details = job?.description || job?.service?.name || job?.type || 'Service details not available';
  const when = formatDateLabel(job?.booking_date, job?.booking_time);
  const budget = job?.total_amount ? formatNpr(job.total_amount) : 'Not fixed';

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/45 p-4" onClick={onClose}>
      <div className="w-full max-w-lg rounded-2xl border border-blue-100 bg-white p-4 shadow-2xl" onClick={(e) => e.stopPropagation()}>
        <div className="flex items-start justify-between gap-3 rounded-xl bg-gradient-to-r from-blue-600 to-cyan-500 p-3 text-white">
          <div>
            <p className="text-xs font-semibold uppercase tracking-wide text-white/85">Success</p>
            <h2 className="text-base font-bold">You accepted! Customer details unlocked</h2>
          </div>
          <button type="button" onClick={onClose} className="rounded-lg bg-white/15 p-1.5 hover:bg-white/25">
            <X size={15} />
          </button>
        </div>

        <div className="mt-3 grid grid-cols-1 gap-2.5 sm:grid-cols-2">
          <DetailCard icon={<User size={14} />} label="Customer Name" value={customer?.name || 'Customer'} />
          <DetailCard icon={<Phone size={14} />} label="Phone Number" value={customer?.phone || 'Not available'} />
          <DetailCard icon={<MapPinned size={14} />} label="Full Address" value={location} span="sm:col-span-2" />
          <DetailCard icon={<ClipboardList size={14} />} label="Service Details" value={details} span="sm:col-span-2" />
          <DetailCard icon={<CalendarDays size={14} />} label="Date & Time" value={when} />
          <DetailCard icon={<Wallet size={14} />} label="Budget" value={budget} />
        </div>

        <div className="mt-3 grid grid-cols-2 gap-2">
          <button
            type="button"
            onClick={() => onNavigate(location)}
            className="inline-flex items-center justify-center gap-1.5 rounded-lg border border-blue-200 bg-blue-50 px-3 py-2 text-xs font-semibold text-blue-700 hover:bg-blue-100"
          >
            <MapPinned size={14} />
            Get Directions
          </button>
          <button
            type="button"
            onClick={onClose}
            className="inline-flex items-center justify-center gap-1.5 rounded-lg border border-gray-200 bg-white px-3 py-2 text-xs font-semibold text-gray-700 hover:bg-gray-50"
          >
            Close
          </button>
        </div>
      </div>
    </div>
  );
}

function DetailCard({ icon, label, value, span = '' }) {
  return (
    <div className={`rounded-xl border border-gray-200 bg-white p-2.5 ${span}`}>
      <p className="mb-1 inline-flex items-center gap-1.5 text-[11px] font-semibold uppercase tracking-wide text-gray-500">
        {icon}
        {label}
      </p>
      <p className="text-sm font-semibold text-gray-800">{value}</p>
    </div>
  );
}

import { useState, useEffect } from "react";
import { IcPhone, IcClose, IcMic, IcSpeaker, IcMapPin } from "../Icons";
import Avatar from "../Avatar";

const VISUALIZER_BAR_HEIGHTS = [14, 24, 36, 22, 30];

export default function CallModal({ user = {}, onClose }) {
  const [status, setStatus]     = useState("Connecting...");
  const [isMuted, setIsMuted]   = useState(false);
  const [isSpeaker, setIsSpeaker] = useState(false);
  const [duration, setDuration] = useState(0);

  // Simulate call connection and duration
  useEffect(() => {
    let timer;
    const connectTimer = setTimeout(() => {
      setStatus("Connected");
      timer = setInterval(() => setDuration(d => d + 1), 1000);
    }, 2500);

    return () => {
      clearTimeout(connectTimer);
      clearInterval(timer);
    };
  }, []);

  const formatDuration = (sec) => {
    const m = Math.floor(sec / 60).toString().padStart(2, "0");
    const s = (sec % 60).toString().padStart(2, "0");
    return `${m}:${s}`;
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/90 backdrop-blur-sm animate-fade-in">
      <div className="flex flex-col items-center justify-between w-full h-full max-w-md p-8 text-center text-white">
        
        {/* Top Info */}
        <div className="flex flex-col items-center mt-12 gap-4 animate-slide-up">
          <Avatar user={user} size="xl" className="w-32 h-32 border-4 border-white/10 shadow-2xl" />
          
          <div className="space-y-1">
            <h2 className="text-2xl font-bold tracking-tight">{user.name || "Customer"}</h2>
            <p className="text-sm font-medium text-white/50 flex items-center justify-center gap-1.5">
              {status === "Connected" ? (
                <span className="text-green-400 animate-pulse">● {formatDuration(duration)}</span>
              ) : (
                status
              )}
            </p>
          </div>
        </div>

        {/* Middle Visualization (optional) */}
        <div className="flex-1 flex items-center justify-center w-full">
           <div className={`w-full max-w-[200px] h-24 flex items-center justify-center gap-1 ${status === "Connected" ? "" : "opacity-30"}`}>
             {[...Array(5)].map((_, i) => (
               <div 
                 key={i} 
                 className="w-1.5 bg-white/40 rounded-full animate-pulse" 
                 style={{ 
                   height: status === "Connected" ? `${VISUALIZER_BAR_HEIGHTS[i]}px` : "4px",
                   animationDuration: "0.8s",
                   animationDelay: `${i * 0.1}s` 
                 }}
               />
             ))}
           </div>
        </div>

        {/* Bottom Actions */}
        <div className="w-full pb-12 space-y-8 animate-slide-up" style={{animationDelay: "0.1s"}}>
            
            {/* Control Row */}
            <div className="flex items-center justify-evenly px-4">
              <button 
                onClick={() => setIsMuted(!isMuted)}
                className={`flex flex-col items-center gap-2 group transition-all ${isMuted ? "text-white" : "text-white/50 hover:text-white"}`}
              >
                <div className={`w-14 h-14 rounded-full flex items-center justify-center border transition-all ${isMuted ? "bg-white text-black border-white" : "border-white/20 bg-white/5"}`}>
                  <IcMic size={24} color="currentColor" />
                </div>
                <span className="text-xs font-medium">Mute</span>
              </button>

              <button 
                onClick={() => setIsSpeaker(!isSpeaker)}
                className={`flex flex-col items-center gap-2 group transition-all ${isSpeaker ? "text-white" : "text-white/50 hover:text-white"}`}
              >
                <div className={`w-14 h-14 rounded-full flex items-center justify-center border transition-all ${isSpeaker ? "bg-white text-black border-white" : "border-white/20 bg-white/5"}`}>
                  <IcSpeaker size={24} color="currentColor" />
                </div>
                <span className="text-xs font-medium">Speaker</span>
              </button>
            </div>

            {/* End Call */}
            <div className="flex justify-center">
              <button 
                onClick={onClose}
                className="w-20 h-20 bg-red-500 rounded-full flex items-center justify-center text-white shadow-lg shadow-red-500/30 hover:bg-red-600 hover:scale-105 active:scale-95 transition-all"
              >
                <IcPhone size={32} className="rotate-[135deg]" />
              </button>
            </div>

        </div>
      </div>
    </div>
  );
}

