﻿import { useState, useEffect } from 'react';
import { adminAPI } from '../../services/api';
import { MessageCircle, MapPin, Phone, UserCheck, UserPlus } from 'lucide-react';
import ReassignTechnicianModal from '../../components/admin/common/ReassignTechnicianModal';

const AllJobs = () => {
  const [jobs, setJobs] = useState([]);
  const [loading, setLoading] = useState(true);
  const [filter, setFilter] = useState('all');
  const [error, setError] = useState('');
  const [selectedJob, setSelectedJob] = useState(null);
  const [showReassignModal, setShowReassignModal] = useState(false);

  const fetchJobs = async (currentFilter) => {
    setLoading(true);
    setError('');
    try {
      const params = currentFilter !== 'all' ? { status: currentFilter } : {};
      const response = await adminAPI.getAllBookings(params);
      if (response.data.success) {
        const payload = response.data?.data?.bookings ?? response.data?.data ?? [];
        setJobs(Array.isArray(payload) ? payload : []);
      } else {
        setJobs([]);
        setError(response.data?.message || 'Failed to fetch jobs.');
      }
    } catch (err) {
      console.error('Error fetching jobs:', err);
      setJobs([]);
      setError(err.response?.data?.message || 'Unable to load jobs right now.');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchJobs(filter);
  }, [filter]);

  const getStatusProgress = (status) => {
    const map = { pending: 25, accepted: 50, 'in-progress': 75, completed: 100 };
    return map[status] || 0;
  };

  const getStatusColor = (status) => {
    const map = {
      completed: 'bg-green-100 text-green-700',
      'in-progress': 'bg-blue-100 text-blue-700',
      accepted: 'bg-blue-100 text-blue-700',
      cancelled: 'bg-red-100 text-red-700',
      pending: 'bg-yellow-100 text-yellow-700',
    };
    return map[status] || 'bg-gray-100 text-gray-700';
  };

  const formatStatusLabel = (status) => {
    const labels = {
      pending: 'Pending',
      accepted: 'Accepted',
      'in-progress': 'In Progress',
      completed: 'Completed',
      cancelled: 'Cancelled',
      all: 'All',
    };
    return labels[status] || status;
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center h-full">
        <div className="text-gray-700 text-xl">Loading jobs...</div>
      </div>
    );
  }

  return (
    <div className="admin-page">
      {/* Header */}
      <div className="flex items-center justify-between flex-wrap gap-4">
        <div>
          <h1 className="admin-page-title mb-2">All Jobs</h1>
          <p className="admin-page-subtitle">Manage and track all service bookings</p>
        </div>
        <div className="flex gap-2 flex-wrap">
          {['all', 'pending', 'accepted', 'in-progress', 'completed'].map((status) => (
            <button
              key={status}
              onClick={() => setFilter(status)}
              className={`px-4 py-2 rounded-lg text-sm font-medium transition-all ${
                filter === status
                  ? 'bg-blue-600 text-white'
                  : 'bg-white border border-gray-200 text-gray-700 hover:bg-gray-100'
              }`}
            >
              {formatStatusLabel(status)}
            </button>
          ))}
        </div>
      </div>

      {error && (
        <div className="admin-card border border-red-200 p-4">
          <p className="text-red-700 text-sm">{error}</p>
        </div>
      )}

      {jobs.length === 0 ? (
        <div className="admin-card p-12 text-center">
          <p className="text-gray-800 text-lg">No jobs found</p>
        </div>
      ) : (
        <div className="space-y-4">
          {jobs.map((job) => {
            const hasTechnician = Boolean(job.technician);
            const isClosedStatus = ['completed', 'cancelled'].includes(job.status);

            return (
              <div key={job.id} className="admin-card-pad hover:shadow-lg">
                <div className="flex items-start justify-between mb-4 gap-4">
                  {/* Job Info */}
                  <div className="flex-1 min-w-0">
                    <div className="flex items-center gap-3 mb-2 flex-wrap">
                      <h3 className="text-xl font-semibold text-gray-800">
                        {job.service?.icon} {job.service?.name || 'Service'}
                      </h3>
                      <span className="text-gray-700 text-sm font-medium">#{job.id}</span>
                      <span className={`admin-chip ${getStatusColor(job.status)}`}>
                        {formatStatusLabel(job.status)}
                      </span>
                    </div>

                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-2 text-sm text-gray-700">
                      <div>
                        <p className="mb-1">
                          <strong className="text-gray-800">Customer:</strong> {job.customer?.name || '—'}
                        </p>
                        <p className="mb-1">
                          <strong className="text-gray-800">Technician:</strong>{' '}
                          {hasTechnician
                            ? <span className="text-green-700">{job.technician.name}</span>
                            : <span className="text-amber-700">Not assigned</span>
                          }
                        </p>
                      </div>
                      <div>
                        <p className="mb-1 flex items-center gap-2">
                          <Phone size={13} className="flex-shrink-0" />
                          <span><strong className="text-gray-800">Contact Number:</strong> {job.customer?.phone || '—'}</span>
                        </p>
                        <p className="mb-1 flex items-center gap-2">
                          <MapPin size={13} className="flex-shrink-0" />
                          <span className="truncate"><strong className="text-gray-800">Location:</strong> {job.location || '—'}</span>
                        </p>
                      </div>
                    </div>

                    {job.description && (
                      <p className="text-gray-700 text-sm font-medium mt-1 truncate">
                        Note: {job.description}
                      </p>
                    )}
                  </div>

                  {/* Action Buttons */}
                  <div className="flex flex-col gap-2 flex-shrink-0">
                    {/* Assign / Reassign button — hidden for completed/cancelled */}
                    {!isClosedStatus && (
                      <button
                        onClick={() => {
                          setSelectedJob(job);
                          setShowReassignModal(true);
                        }}
                        className={`flex items-center gap-2 text-sm px-4 py-2 rounded-lg transition font-medium ${
                          hasTechnician
                            ? 'bg-amber-500 hover:bg-amber-600 text-white border border-amber-500'
                            : 'bg-blue-600 hover:bg-blue-700 text-white border border-blue-600'
                        }`}
                      >
                        {hasTechnician
                          ? <><UserCheck size={15} /> Reassign</>
                          : <><UserPlus size={15} /> Assign Technician</>
                        }
                      </button>
                    )}

                    <button className="btn-primary text-sm px-4 py-2 flex items-center gap-2">
                      <MessageCircle size={15} />
                      Chat
                    </button>
                  </div>
                </div>

                {/* Progress Bar */}
                <div className="space-y-2">
                  <div className="flex items-center justify-between text-sm">
                    <span className="text-gray-700">Progress</span>
                    <span className="text-gray-800 font-medium">{getStatusProgress(job.status)}%</span>
                  </div>
                  <div className="relative h-2 bg-gray-200 rounded-full overflow-hidden">
                    <div
                      className={`absolute top-0 left-0 h-full transition-all duration-500 ${
                        job.status === 'completed'
                          ? 'bg-gradient-to-r from-green-500 to-green-400'
                          : job.status === 'cancelled'
                          ? 'bg-gradient-to-r from-red-500 to-red-400'
                          : 'bg-gradient-to-r from-blue-500 to-cyan-400'
                      }`}
                      style={{ width: `${getStatusProgress(job.status)}%` }}
                    />
                  </div>
                  <div className="flex items-center justify-between text-sm text-gray-700 font-medium">
                    {['pending', 'accepted', 'in-progress', 'completed'].map((s) => (
                      <span
                        key={s}
                        className={
                          job.status === s
                            ? s === 'completed' ? 'text-green-700 font-semibold' : 'text-blue-700 font-semibold'
                            : ''
                        }
                      >
                        {formatStatusLabel(s)}
                      </span>
                    ))}
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      )}

      <ReassignTechnicianModal
        job={selectedJob}
        isOpen={showReassignModal}
        onClose={() => {
          setShowReassignModal(false);
          setSelectedJob(null);
        }}
        onSuccess={() => fetchJobs(filter)}
      />
    </div>
  );
};

export default AllJobs;

﻿import { useState, useEffect } from 'react';
import { adminAPI } from '../../services/api';
import { MessageCircle, Search } from 'lucide-react';
import { useNavigate } from 'react-router-dom';
import { getImageUrl } from '../../utils/imageHelper';

const AllTechnicians = () => {
  const navigate = useNavigate();
  const [technicians, setTechnicians] = useState([]);
  const [loading, setLoading] = useState(true);
  const [activeFilter, setActiveFilter] = useState('all');
  const [searchQuery, setSearchQuery] = useState('');

  useEffect(() => {
    fetchTechnicians();
  }, []);

  const fetchTechnicians = async () => {
    try {
      const response = await adminAPI.getAllTechnicians();
      
      if (response.data.success) {
        setTechnicians(response.data.data || []);
      }
    } catch (error) {
      console.error('Error fetching technicians:', error);
    } finally {
      setLoading(false);
    }
  };

  const getServiceTabs = () => {
    const servicesMap = new Map();
    
    technicians.forEach(tech => {
      if (tech.services && Array.isArray(tech.services)) {
        tech.services.forEach(service => {
          if (!servicesMap.has(service.name)) {
            servicesMap.set(service.name, service.icon || '🔧');
          }
        });
      }
    });
    
    return Array.from(servicesMap.entries()).map(([name, icon]) => ({ name, icon }));
  };

  const serviceTabs = getServiceTabs();

  const filterByService = (techs) => {
    if (activeFilter === 'all') return techs;
    
    return techs.filter(tech => 
      tech.services && tech.services.some(service => 
        service.name.toLowerCase() === activeFilter.toLowerCase()
      )
    );
  };

  const filterBySearch = (techs) => {
    if (!searchQuery.trim()) return techs;
    
    const query = searchQuery.toLowerCase();
    return techs.filter(tech => 
      tech.name?.toLowerCase().includes(query) ||
      tech.email?.toLowerCase().includes(query) ||
      tech.phone?.includes(query)
    );
  };

  const filteredTechnicians = filterBySearch(filterByService(technicians));

  const calculateEarnings = (tech) => {
    return (tech.completed_jobs || 0) * 1000;
  };

  const handleContactTechnician = (tech) => {
    navigate('/admin/messages', { 
      state: { 
        openSupportTicket: true,
        technicianId: tech.id,
        technicianName: tech.name 
      } 
    });
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center h-full">
        <div className="text-gray-700 text-xl">Loading technicians...</div>
      </div>
    );
  }

  return (
    <div className="admin-page">
      {/* Header with Search */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="admin-page-title mb-2">All Technicians</h1>
          <p className="admin-page-subtitle">Manage your service providers</p>
        </div>

        {/* Search Bar */}
        <div className="relative w-80">
          <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-500" size={18} />
          <input
            type="text"
            placeholder="Search technicians..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="w-full pl-10 pr-4 py-2 bg-white border border-gray-300 rounded-lg text-gray-800 text-sm placeholder-gray-400 focus:outline-none focus:ring-2 focus:ring-blue-500 transition-all"
          />
        </div>
      </div>

      {/* Service Category Tabs */}
      <div className="flex gap-2 border-b border-gray-200 pb-4">
        <button
          onClick={() => setActiveFilter('all')}
          className={`px-6 py-2 rounded-t-lg text-sm font-medium transition-all ${
            activeFilter === 'all'
              ? 'bg-blue-600 text-white'
              : 'text-gray-700 hover:text-gray-900 hover:bg-blue-50'
          }`}
        >
          All
        </button>
        {serviceTabs.map((service, index) => (
          <button
            key={index}
            onClick={() => setActiveFilter(service.name)}
            className={`px-6 py-2 rounded-t-lg text-sm font-medium transition-all flex items-center gap-2 ${
              activeFilter === service.name
                ? 'bg-blue-600 text-white'
                : 'text-gray-700 hover:text-gray-900 hover:bg-blue-50'
            }`}
          >
            <span>{service.icon}</span>
            {service.name}
          </button>
        ))}
      </div>

      {/* Technicians Grid */}
      {filteredTechnicians.length === 0 ? (
        <div className="admin-card p-12 text-center">
          <p className="text-gray-800 text-lg">No technicians found</p>
        </div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {filteredTechnicians.map((tech) => {
            const earnings = calculateEarnings(tech);
            const isActive = tech.is_active && tech.completed_jobs > 0;
            const status = isActive ? 'Active' : 'Available';
            
            return (
              <div key={tech.id} className="admin-card-pad hover:shadow-lg">
                {/* Header with Status Badge */}
                <div className="flex items-start justify-between mb-4">
                  <div className="flex-1">
                    <h3 className="text-xl font-semibold text-gray-800 mb-2">{tech.name}</h3>
                    
                    {/* Profession Badge */}
                    <div className="flex flex-wrap gap-2 mb-3">
                      {tech.services && tech.services.length > 0 ? (
                        tech.services.map((service) => (
                          <span 
                            key={service.id}
                            className="admin-chip bg-blue-100 text-blue-700 text-sm"
                          >
                            {service.name}
                          </span>
                        ))
                      ) : (
                        <span className="text-gray-700 text-sm italic">No service assigned</span>
                      )}
                    </div>

                    {/* Status Badge */}
                    <span className={`inline-block admin-chip ${
                      isActive 
                        ? 'bg-green-100 text-green-700' 
                        : 'bg-blue-100 text-blue-700'
                    }`}>
                      {status}
                    </span>
                  </div>

                  {/* Profile Picture */}
                  <div className="w-16 h-16 rounded-full overflow-hidden bg-gradient-to-br from-blue-500 to-cyan-500 flex items-center justify-center flex-shrink-0 shadow-lg">
                    {(tech.profile_image || tech.profileImage) ? (
                      <img 
                        src={getImageUrl(tech.profile_image || tech.profileImage)}
                        alt={tech.name}
                        className="w-full h-full object-cover"
                      />
                    ) : (
                      <span className="text-white font-bold text-2xl">
                        {tech.name ? tech.name.charAt(0).toUpperCase() : '?'}
                      </span>
                    )}
                  </div>
                </div>

                {/* Stats Grid */}
                <div className="grid grid-cols-2 gap-3 mb-4">
                  <div className="bg-gray-50 rounded-lg p-3 border border-gray-200">
                    <p className="text-gray-700 text-sm font-semibold mb-1">Total Jobs</p>
                    <p className="text-gray-800 text-xl font-bold">{tech.total_jobs || 0}</p>
                  </div>
                  <div className="bg-gray-50 rounded-lg p-3 border border-gray-200">
                    <p className="text-gray-700 text-sm font-semibold mb-1">Completed</p>
                    <p className="text-gray-800 text-xl font-bold">{tech.completed_jobs || 0}</p>
                  </div>
                </div>

                {/* Contact & Earnings */}
                <div className="space-y-2 mb-4">
                  <p className="text-gray-700 text-sm"><strong>Phone:</strong> {tech.phone || 'N/A'}</p>
                  <p className="text-blue-700 text-lg font-bold">
                    NPR {earnings.toLocaleString()}
                  </p>
                </div>

                {/* Contact Button */}
                <button 
                  onClick={() => handleContactTechnician(tech)}
                  className="btn-primary w-full flex items-center justify-center gap-2 text-sm py-2"
                >
                  <MessageCircle size={16} />
                  Contact
                </button>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
};

export default AllTechnicians;

import { useState, useEffect } from 'react';
import { adminAPI } from '../../services/api';
import { AlertCircle, Upload, X } from 'lucide-react';

const HireTechnician = () => {
  const [formData, setFormData] = useState({
    name: '',
    email: '',
    phone: '',
    address: '',
    services: [],
    bank_name: '',
    account_number: '',
    account_holder_name: '',
  });
  
  const [profileImage, setProfileImage] = useState(null);
  const [imagePreview, setImagePreview] = useState(null);
  const [services, setServices] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  useEffect(() => {
    fetchServices();
  }, []);

  const fetchServices = async () => {
    try {
      const response = await adminAPI.getAllServices();
      if (response.data.success) {
        setServices(response.data.data || []);
      }
    } catch (err) {
      console.error('Error fetching services:', err);
    }
  };

  const handleChange = (e) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value,
    });
    setError('');
  };

  const handleServiceToggle = (serviceId) => {
    setFormData(prev => ({
      ...prev,
      services: prev.services.includes(serviceId)
        ? prev.services.filter(id => id !== serviceId)
        : [...prev.services, serviceId]
    }));
    setError('');
  };

  const handleImageChange = (e) => {
    const file = e.target.files[0];
    if (file) {
      // Validate file type
      if (!file.type.startsWith('image/')) {
        setError('Please select a valid image file');
        return;
      }
      
      // Validate file size (max 5MB)
      if (file.size > 5 * 1024 * 1024) {
        setError('Image size should be less than 5MB');
        return;
      }

      setProfileImage(file);
      
      // Create preview
      const reader = new FileReader();
      reader.onloadend = () => {
        setImagePreview(reader.result);
      };
      reader.readAsDataURL(file);
    }
  };

  const removeImage = () => {
    setProfileImage(null);
    setImagePreview(null);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    
    // Validation
    if (!formData.name || !formData.email || !formData.phone) {
      setError('Please fill in all required fields');
      return;
    }

    if (formData.services.length === 0) {
      setError('Please select at least one service');
      return;
    }

    setLoading(true);
    setError('');

    try {
      // Create FormData for file upload
      const submitData = new FormData();
      submitData.append('name', formData.name);
      submitData.append('email', formData.email);
      submitData.append('phone', formData.phone);
      submitData.append('address', formData.address);
      submitData.append('services', JSON.stringify(formData.services));
      submitData.append('bank_name', formData.bank_name);
      submitData.append('account_number', formData.account_number);
      submitData.append('account_holder_name', formData.account_holder_name);
      
      if (profileImage) {
        submitData.append('profile_image', profileImage);
      }

      const response = await adminAPI.createTechnician(submitData);

      if (response.data.success) {
        // Don't show success toast - notification will appear in dropdown instead

        // Reset form
        setFormData({
          name: '',
          email: '',
          phone: '',
          address: '',
          services: [],
          bank_name: '',
          account_number: '',
          account_holder_name: '',
        });
        setProfileImage(null);
        setImagePreview(null);
      }
    } catch (err) {
      setError(err.response?.data?.message || 'Failed to create technician');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="max-w-4xl mx-auto admin-page">
      {/* Header */}
      <div>
        <h1 className="admin-page-title mb-2">Hire New Technician</h1>
        <p className="admin-page-subtitle">Add a new service provider to your platform</p>
      </div>

      {/* Error Message */}
      {error && (
        <div className="bg-red-50 border border-red-200 rounded-lg p-4 flex items-center gap-3">
          <AlertCircle className="text-red-600" size={24} />
          <p className="text-red-700">{error}</p>
        </div>
      )}

      {/* Form */}
      <form onSubmit={handleSubmit} className="admin-card p-6 space-y-6">
        {/* Profile Picture Upload */}
        <div>
          <h2 className="admin-section-title mb-4">Profile Picture (Optional)</h2>
          <div className="flex items-center gap-6">
            {/* Preview */}
            <div className="w-32 h-32 rounded-full bg-gradient-to-br from-blue-500 to-cyan-500 flex items-center justify-center text-white text-4xl font-bold overflow-hidden">
              {imagePreview ? (
                <img src={imagePreview} alt="Preview" className="w-full h-full object-cover" />
              ) : (
                <span>{formData.name ? formData.name.charAt(0).toUpperCase() : '?'}</span>
              )}
            </div>

            {/* Upload Button */}
            <div className="flex-1">
              {!imagePreview ? (
                <label className="btn-secondary-light cursor-pointer inline-flex items-center gap-2">
                  <Upload size={18} />
                  Upload Photo
                  <input
                    type="file"
                    accept="image/*"
                    onChange={handleImageChange}
                    className="hidden"
                  />
                </label>
              ) : (
                <button
                  type="button"
                  onClick={removeImage}
                  className="btn-secondary-light inline-flex items-center gap-2"
                >
                  <X size={18} />
                  Remove Photo
                </button>
              )}
              <p className="text-gray-700 text-sm font-medium mt-2">
                Upload JPG, PNG, or GIF (max 5MB).
              </p>
            </div>
          </div>
        </div>

        {/* Personal Information */}
        <div>
          <h2 className="admin-section-title mb-4">Personal Information</h2>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div>
              <label className="block text-gray-700 text-sm font-medium mb-2">
                Full Name *
              </label>
              <input
                type="text"
                name="name"
                value={formData.name}
                onChange={handleChange}
                placeholder="Enter technician name"
                className="admin-input"
                required
              />
            </div>

            <div>
              <label className="block text-gray-700 text-sm font-medium mb-2">
                Contact Number *
              </label>
              <input
                type="tel"
                name="phone"
                value={formData.phone}
                onChange={handleChange}
                placeholder="+977 98XXXXXXXX"
                className="admin-input"
                required
              />
              <p className="text-gray-700 text-sm mt-1">Example: 9876543210</p>
            </div>

            <div>
              <label className="block text-gray-700 text-sm font-medium mb-2">
                Email *
              </label>
              <input
                type="email"
                name="email"
                value={formData.email}
                onChange={handleChange}
                placeholder="email@example.com"
                className="admin-input"
                required
              />
              <p className="text-gray-700 text-sm mt-1">Default technician password: Technician@123</p>
            </div>

            <div>
              <label className="block text-gray-700 text-sm font-medium mb-2">
                Address
              </label>
              <input
                type="text"
                name="address"
                value={formData.address}
                onChange={handleChange}
                placeholder="Enter address"
                className="admin-input"
              />
            </div>
          </div>
        </div>

        {/* Bank Details */}
        <div>
          <h2 className="admin-section-title mb-4">Bank Details</h2>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div>
              <label className="block text-gray-700 text-sm font-medium mb-2">
                Bank Name
              </label>
              <input
                type="text"
                name="bank_name"
                value={formData.bank_name}
                onChange={handleChange}
                placeholder="e.g., Nepal Bank Limited"
                className="admin-input"
              />
            </div>

            <div>
              <label className="block text-gray-700 text-sm font-medium mb-2">
                Account Number
              </label>
              <input
                type="text"
                name="account_number"
                value={formData.account_number}
                onChange={handleChange}
                placeholder="Enter account number"
                className="admin-input"
              />
            </div>

            <div className="md:col-span-2">
              <label className="block text-gray-700 text-sm font-medium mb-2">
                Account Holder Name
              </label>
              <input
                type="text"
                name="account_holder_name"
                value={formData.account_holder_name}
                onChange={handleChange}
                placeholder="Name as per bank account"
                className="admin-input"
              />
            </div>
          </div>
          <p className="text-gray-700 text-sm mt-2">
            Bank details are used for monthly payout transfers.
          </p>
        </div>

        {/* Services */}
        <div>
          <h2 className="admin-section-title mb-4">Services / Specializations *</h2>
          <div className="grid grid-cols-2 md:grid-cols-3 gap-3">
            {services.map((service) => (
              <button
                key={service.id}
                type="button"
                onClick={() => handleServiceToggle(service.id)}
                className={`p-4 rounded-lg border-2 transition-all text-left ${
                  formData.services.includes(service.id)
                    ? 'border-blue-400 bg-blue-50'
                    : 'border-gray-300 bg-white hover:border-blue-300'
                }`}
              >
                <div className="text-2xl mb-2">{service.icon}</div>
                <div className="text-gray-800 font-medium">{service.name}</div>
              </button>
            ))}
          </div>
          {formData.services.length === 0 && (
            <p className="text-red-400 text-sm mt-2">Please select at least one service</p>
          )}
        </div>

        {/* Password Info */}
        <div className="bg-blue-50 border border-blue-200 rounded-lg p-4">
          <h3 className="text-blue-700 font-semibold mb-2">Auto-generated Password</h3>
          <p className="text-gray-800 text-sm">
            Password will be generated upon submission: <strong>Technician@123</strong>
          </p>
          <p className="text-gray-700 text-sm mt-1">
            Technician can change this password after first login
          </p>
        </div>

        {/* Submit Button */}
        <button
          type="submit"
          disabled={loading}
          className="btn-primary w-full text-lg py-4 disabled:opacity-50 disabled:cursor-not-allowed"
        >
          {loading ? 'Hiring Technician...' : 'Hire Technician'}
        </button>
      </form>
    </div>
  );
};

export default HireTechnician;

﻿import { useEffect, useMemo, useState } from 'react';
import { Headphones, MessageCircle, Plus, Send } from 'lucide-react';
import toast from 'react-hot-toast';
import { messagesAPI } from '../../services/api';
import { getSocket, joinConversation } from '../../services/socket';

const toDateLabel = (value) => {
  if (!value) return '';
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return '';
  return date.toLocaleString();
};

const Messages = () => {
  const [activeTab, setActiveTab] = useState('booking');

  const [conversations, setConversations] = useState([]);
  const [selectedConversationId, setSelectedConversationId] = useState(null);
  const [bookingMessages, setBookingMessages] = useState([]);
  const [loadingList, setLoadingList] = useState(true);
  const [loadingBookingMessages, setLoadingBookingMessages] = useState(false);

  const [supportConversations, setSupportConversations] = useState([]);
  const [supportTechnicians, setSupportTechnicians] = useState([]);
  const [selectedSupportConversationId, setSelectedSupportConversationId] = useState(null);
  const [supportMessages, setSupportMessages] = useState([]);
  const [loadingSupportList, setLoadingSupportList] = useState(false);
  const [loadingSupportMessages, setLoadingSupportMessages] = useState(false);
  const [selectedTechnicianId, setSelectedTechnicianId] = useState('');

  const [replyText, setReplyText] = useState('');

  const selectedConversation = useMemo(
    () => conversations.find((item) => item.id === selectedConversationId) || null,
    [conversations, selectedConversationId]
  );

  const selectedSupportConversation = useMemo(
    () => supportConversations.find((item) => item.id === selectedSupportConversationId) || null,
    [supportConversations, selectedSupportConversationId]
  );

  const loadConversations = async () => {
    try {
      setLoadingList(true);
      const response = await messagesAPI.getConversations();
      const list = response.data?.data || [];
      setConversations(list);
      if (!selectedConversationId && list.length > 0) {
        setSelectedConversationId(list[0].id);
      }
    } catch (error) {
      console.error('Load conversations error:', error);
      toast.error(error.response?.data?.message || 'Failed to load conversations');
    } finally {
      setLoadingList(false);
    }
  };

  const loadBookingMessages = async (conversationId) => {
    if (!conversationId) return;
    try {
      setLoadingBookingMessages(true);
      const response = await messagesAPI.getConversationMessages(conversationId);
      setBookingMessages(response.data?.data?.messages || []);
      setConversations((prev) =>
        prev.map((item) => (item.id === conversationId ? { ...item, unread_count: 0 } : item))
      );
    } catch (error) {
      console.error('Load messages error:', error);
      toast.error(error.response?.data?.message || 'Failed to load messages');
    } finally {
      setLoadingBookingMessages(false);
    }
  };

  const loadSupportTechnicians = async () => {
    try {
      const response = await messagesAPI.getSupportTechnicians();
      setSupportTechnicians(response.data?.data || []);
    } catch (error) {
      console.error('Load support technicians error:', error);
      toast.error(error.response?.data?.message || 'Failed to load technicians');
    }
  };

  const loadSupportConversations = async () => {
    try {
      setLoadingSupportList(true);
      const response = await messagesAPI.getSupportConversations();
      const list = response.data?.data || [];
      setSupportConversations(list);
      if (!selectedSupportConversationId && list.length > 0) {
        setSelectedSupportConversationId(list[0].id);
      }
    } catch (error) {
      console.error('Load support conversations error:', error);
      toast.error(error.response?.data?.message || 'Failed to load support conversations');
    } finally {
      setLoadingSupportList(false);
    }
  };

  const loadSupportMessages = async (conversationId) => {
    if (!conversationId) return;
    try {
      setLoadingSupportMessages(true);
      const response = await messagesAPI.getSupportConversationMessages(conversationId);
      setSupportMessages(response.data?.data?.messages || []);
      setSupportConversations((prev) =>
        prev.map((item) => (item.id === conversationId ? { ...item, unread_count: 0 } : item))
      );
    } catch (error) {
      console.error('Load support messages error:', error);
      toast.error(error.response?.data?.message || 'Failed to load support messages');
    } finally {
      setLoadingSupportMessages(false);
    }
  };

  useEffect(() => {
    loadConversations();
    loadSupportTechnicians();
    loadSupportConversations();
  }, []);

  useEffect(() => {
    loadBookingMessages(selectedConversationId);
  }, [selectedConversationId]);

  useEffect(() => {
    loadSupportMessages(selectedSupportConversationId);
  }, [selectedSupportConversationId]);

  useEffect(() => {
    if (!selectedConversationId) return;
    joinConversation(selectedConversationId);
    const socket = getSocket();
    if (!socket) return;

    const onMessage = (payload) => {
      if (payload.conversation_id !== selectedConversationId) return;
      setBookingMessages((prev) => [...prev, payload]);
      setConversations((prev) => prev.map((item) => (
        item.id === selectedConversationId
          ? { ...item, last_message: payload }
          : item
      )));
    };

    socket.on('chat:message', onMessage);
    return () => socket.off('chat:message', onMessage);
  }, [selectedConversationId]);

  useEffect(() => {
    if (!selectedSupportConversationId) return;
    const socket = getSocket();
    if (!socket) return;

    const onSupportMessage = (payload) => {
      if (payload.conversation_id !== selectedSupportConversationId) return;
      setSupportMessages((prev) => [...prev, payload]);
      setSupportConversations((prev) => prev.map((item) => (
        item.id === selectedSupportConversationId
          ? { ...item, last_message: payload }
          : item
      )));
    };

    socket.on('support:message', onSupportMessage);
    return () => socket.off('support:message', onSupportMessage);
  }, [selectedSupportConversationId]);

  const handleOpenSupportConversation = async () => {
    if (!selectedTechnicianId) {
      toast.error('Select a technician first');
      return;
    }

    try {
      const response = await messagesAPI.createSupportConversation(selectedTechnicianId);
      const conversation = response.data?.data;
      if (conversation?.id) {
        setSelectedSupportConversationId(conversation.id);
      }
      await loadSupportConversations();
      setActiveTab('support');
    } catch (error) {
      toast.error(error.response?.data?.message || 'Failed to open support conversation');
    }
  };

  const handleSendReply = async () => {
    if (!selectedSupportConversationId || !replyText.trim()) return;
    try {
      await messagesAPI.sendSupportMessage(selectedSupportConversationId, replyText.trim());
      setReplyText('');
      await loadSupportMessages(selectedSupportConversationId);
      await loadSupportConversations();
    } catch (error) {
      console.error('Send message error:', error);
      toast.error(error.response?.data?.message || 'Failed to send message');
    }
  };

  return (
    <div className="h-full flex flex-col admin-page">
      {/* Header */}
      <div>
        <h1 className="admin-page-title mb-2">Messages</h1>
        <p className="admin-page-subtitle">Monitor booking chats and manage private technician support</p>
      </div>

      <div className="flex gap-2 border-b border-gray-200">
        <button
          type="button"
          onClick={() => setActiveTab('booking')}
          className={`px-6 py-3 rounded-t-lg text-sm font-medium ${
            activeTab === 'booking' ? 'bg-blue-600 text-white' : 'bg-white text-gray-700'
          }`}
        >
          <span className="flex items-center gap-2">
            <MessageCircle size={16} />
            Booking Conversations (Read Only)
          </span>
        </button>
        <button
          type="button"
          onClick={() => setActiveTab('support')}
          className={`px-6 py-3 rounded-t-lg text-sm font-medium ${
            activeTab === 'support' ? 'bg-blue-600 text-white' : 'bg-white text-gray-700'
          }`}
        >
          <span className="flex items-center gap-2">
            <Headphones size={16} />
            Technician Support
          </span>
        </button>
      </div>

      {activeTab === 'booking' ? (
        <div className="admin-card flex-1 flex overflow-hidden">
        {/* List Panel */}
        <div className="w-96 border-r border-gray-200 flex flex-col bg-white">
          <div className="p-4 border-b border-gray-200">
            <h3 className="text-gray-800 font-semibold">Conversation List</h3>
          </div>

          <div className="flex-1 overflow-y-auto">
            {loadingList ? (
              <div className="p-8 text-center">
                <p className="text-gray-700 text-sm font-medium">Loading conversations...</p>
              </div>
            ) : null}
            {!loadingList && conversations.length === 0 ? (
              <div className="p-8 text-center">
                <MessageCircle size={48} className="mx-auto text-gray-300 mb-3" />
                <p className="text-gray-700 text-sm font-medium">No messages yet</p>
              </div>
            ) : (
              <div className="divide-y divide-gray-100">
                {conversations.map((item) => (
                  <div
                    key={item.id}
                    onClick={() => setSelectedConversationId(item.id)}
                    className={`p-4 hover:bg-blue-50 cursor-pointer transition-colors ${
                      selectedConversationId === item.id ? 'bg-blue-50' : ''
                    } ${item.unread_count > 0 ? 'bg-yellow-50/60' : ''}`}
                  >
                    <div className="flex items-start justify-between mb-2">
                      <div>
                        <p className="text-gray-800 font-medium text-sm">Booking #{item.booking?.id || '-'}</p>
                        <p className="text-gray-800 text-sm">{item.customer?.name || 'Customer'} ↔ {item.technician?.name || 'Technician'}</p>
                      </div>
                      {item.unread_count > 0 ? (
                        <span className="bg-amber-500 text-slate-900 text-xs px-2 py-0.5 rounded-full font-semibold">
                          {item.unread_count}
                        </span>
                      ) : null}
                    </div>
                    <p className="text-gray-700 text-sm truncate">{item.last_message?.message || 'No messages yet'}</p>
                    <p className="text-gray-600 text-sm mt-2">{toDateLabel(item.last_message?.created_at || item.updated_at)}</p>
                  </div>
                ))}
              </div>
            )}
          </div>
        </div>

        {/* Chat Panel */}
        <div className="flex-1 flex flex-col bg-white">
          {!selectedConversation ? (
            <div className="flex-1 flex items-center justify-center">
              <div className="text-center">
                <MessageCircle size={64} className="mx-auto text-gray-300 mb-4" />
                <p className="text-gray-800 text-lg font-medium">Select a conversation</p>
                <p className="text-gray-700 text-sm mt-2">Select a conversation to view and reply.</p>
              </div>
            </div>
          ) : (
            <>
              {/* Chat Header */}
              <div className="p-4 border-b border-gray-200 flex items-center justify-between">
                <div>
                  <p className="text-gray-800 font-semibold">
                    Booking #{selectedConversation.booking?.id || '-'}
                  </p>
                  <p className="text-gray-800 text-sm">
                    {selectedConversation.customer?.name || 'Customer'} ↔ {selectedConversation.technician?.name || 'Technician'}
                  </p>
                </div>
              </div>

              {/* Messages */}
              <div className="flex-1 overflow-y-auto p-4 space-y-4">
                {loadingBookingMessages ? <p className="text-gray-600">Loading messages...</p> : null}
                {!loadingBookingMessages && bookingMessages.length === 0 ? (
                  <p className="text-gray-600">No messages yet for this conversation.</p>
                ) : null}
                {bookingMessages.map((msg) => (
                  <div
                    key={msg.id}
                    className={`flex ${msg.sender_id === Number(localStorage.getItem('user') ? JSON.parse(localStorage.getItem('user')).id : 0) ? 'justify-end' : 'justify-start'}`}
                  >
                    <div className={`max-w-md border ${
                      msg.sender_id === Number(localStorage.getItem('user') ? JSON.parse(localStorage.getItem('user')).id : 0)
                        ? 'bg-blue-600 text-white border-blue-600'
                        : 'bg-gray-100 text-gray-800 border-gray-200'
                    } rounded-lg p-3`}>
                      <p className="text-sm">{msg.message}</p>
                      <p className={`text-xs mt-2 ${msg.sender_id === Number(localStorage.getItem('user') ? JSON.parse(localStorage.getItem('user')).id : 0) ? 'text-blue-100' : 'text-gray-600'}`}>
                        {toDateLabel(msg.created_at)}
                      </p>
                    </div>
                  </div>
                ))}
              </div>

              <div className="p-4 border-t border-gray-200">
                <div className="rounded-lg border border-blue-100 bg-blue-50 p-3">
                  <p className="text-sm font-medium text-blue-700">
                    Admin read-only mode: Booking conversations are visible for monitoring only.
                  </p>
                </div>
              </div>
            </>
          )}
        </div>
        </div>
      ) : null}

      {activeTab === 'support' ? (
        <div className="admin-card flex-1 flex overflow-hidden">
          <div className="w-96 border-r border-gray-200 flex flex-col bg-white">
            <div className="p-4 border-b border-gray-200 space-y-3">
              <h3 className="text-gray-800 font-semibold">Technician Support</h3>
              <div className="flex gap-2">
                <select
                  value={selectedTechnicianId}
                  onChange={(e) => setSelectedTechnicianId(e.target.value)}
                  className="flex-1 rounded-lg border border-gray-300 bg-white px-3 py-2 text-sm text-gray-800"
                >
                  <option value="">Select technician</option>
                  {supportTechnicians.map((tech) => (
                    <option key={tech.id} value={tech.id}>{tech.name}</option>
                  ))}
                </select>
                <button
                  type="button"
                  onClick={handleOpenSupportConversation}
                  className="inline-flex items-center gap-1 rounded-lg bg-blue-600 px-3 py-2 text-sm font-semibold text-white hover:bg-blue-700"
                >
                  <Plus size={14} />
                  Open
                </button>
              </div>
            </div>

            <div className="flex-1 overflow-y-auto">
              {loadingSupportList ? (
                <div className="p-8 text-center">
                  <p className="text-gray-700 text-sm font-medium">Loading support conversations...</p>
                </div>
              ) : null}
              {!loadingSupportList && supportConversations.length === 0 ? (
                <div className="p-8 text-center">
                  <Headphones size={48} className="mx-auto text-gray-300 mb-3" />
                  <p className="text-gray-700 text-sm font-medium">No support conversations yet</p>
                </div>
              ) : (
                <div className="divide-y divide-gray-100">
                  {supportConversations.map((item) => (
                    <div
                      key={item.id}
                      onClick={() => setSelectedSupportConversationId(item.id)}
                      className={`p-4 hover:bg-blue-50 cursor-pointer transition-colors ${
                        selectedSupportConversationId === item.id ? 'bg-blue-50' : ''
                      }`}
                    >
                      <div className="flex items-start justify-between mb-2">
                        <div>
                          <p className="text-gray-800 font-medium text-sm">{item.technician?.name || 'Technician'}</p>
                          <p className="text-gray-700 text-sm">{item.technician?.email || '-'}</p>
                        </div>
                        {item.unread_count > 0 ? (
                          <span className="bg-amber-500 text-slate-900 text-xs px-2 py-0.5 rounded-full font-semibold">
                            {item.unread_count}
                          </span>
                        ) : null}
                      </div>
                      <p className="text-gray-700 text-sm truncate">{item.last_message?.message || 'No messages yet'}</p>
                      <p className="text-gray-600 text-sm mt-2">{toDateLabel(item.last_message?.created_at || item.updated_at)}</p>
                    </div>
                  ))}
                </div>
              )}
            </div>
          </div>

          <div className="flex-1 flex flex-col bg-white">
            {!selectedSupportConversation ? (
              <div className="flex-1 flex items-center justify-center">
                <div className="text-center">
                  <Headphones size={64} className="mx-auto text-gray-300 mb-4" />
                  <p className="text-gray-800 text-lg font-medium">Select a support conversation</p>
                  <p className="text-gray-700 text-sm mt-2">Choose a technician conversation to provide support.</p>
                </div>
              </div>
            ) : (
              <>
                <div className="p-4 border-b border-gray-200 flex items-center justify-between">
                  <div>
                    <p className="text-gray-800 font-semibold">Technician Support</p>
                    <p className="text-gray-800 text-sm">{selectedSupportConversation.technician?.name || 'Technician'}</p>
                  </div>
                </div>

                <div className="flex-1 overflow-y-auto p-4 space-y-4">
                  {loadingSupportMessages ? <p className="text-gray-600">Loading messages...</p> : null}
                  {!loadingSupportMessages && supportMessages.length === 0 ? (
                    <p className="text-gray-600">No support messages yet for this conversation.</p>
                  ) : null}
                  {supportMessages.map((msg) => (
                    <div
                      key={msg.id}
                      className={`flex ${msg.sender_id === Number(localStorage.getItem('user') ? JSON.parse(localStorage.getItem('user')).id : 0) ? 'justify-end' : 'justify-start'}`}
                    >
                      <div className={`max-w-md border ${
                        msg.sender_id === Number(localStorage.getItem('user') ? JSON.parse(localStorage.getItem('user')).id : 0)
                          ? 'bg-blue-600 text-white border-blue-600'
                          : 'bg-gray-100 text-gray-800 border-gray-200'
                      } rounded-lg p-3`}>
                        <p className="text-sm">{msg.message}</p>
                        <p className={`text-xs mt-2 ${msg.sender_id === Number(localStorage.getItem('user') ? JSON.parse(localStorage.getItem('user')).id : 0) ? 'text-blue-100' : 'text-gray-600'}`}>
                          {toDateLabel(msg.created_at)}
                        </p>
                      </div>
                    </div>
                  ))}
                </div>

                <div className="p-4 border-t border-gray-200">
                  <div className="flex gap-2">
                    <input
                      type="text"
                      value={replyText}
                      onChange={(e) => setReplyText(e.target.value)}
                      onKeyDown={(e) => {
                        if (e.key === 'Enter') handleSendReply();
                      }}
                      placeholder="Type support message..."
                      className="flex-1 bg-white border border-gray-300 rounded-lg px-4 py-3 text-gray-800 placeholder-gray-400 focus:outline-none focus:ring-2 focus:ring-blue-500"
                    />
                    <button
                      onClick={handleSendReply}
                      disabled={!replyText.trim()}
                      className="btn-primary px-6 disabled:opacity-50 disabled:cursor-not-allowed"
                    >
                      <Send size={18} />
                    </button>
                  </div>
                </div>
              </>
            )}
          </div>
        </div>
      ) : null}
    </div>
  );
};

export default Messages;

﻿import { useState, useEffect } from 'react';
import { adminAPI } from '../../services/api';
import StatsCard from '../../components/admin/dashboard/StatsCard';
import { Briefcase, Users, DollarSign, Clock } from 'lucide-react';
import { formatCurrency } from '../../utils/helpers';

const Overview = () => {
  const [stats, setStats] = useState({
    totalJobs: 0,
    activeTechnicians: 0,
    monthlyRevenue: 0,
    pendingJobs: 0,
  });
  const [recentJobs, setRecentJobs] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchData();
  }, []);

  const fetchData = async () => {
    try {
      const [statsRes, jobsRes] = await Promise.all([
        adminAPI.getStats(),
        adminAPI.getAllBookings({ limit: 5 }),
      ]);

      if (statsRes.data.success) {
        setStats(statsRes.data.data);
      }

      if (jobsRes.data.success) {
        setRecentJobs(jobsRes.data.data.bookings || []);
      }
    } catch (error) {
      console.error('Error fetching data:', error);
    } finally {
      setLoading(false);
    }
  };

  const getStatusBadge = (status) => {
    const styles = {
      'pending': 'bg-yellow-100 text-yellow-700',
      'accepted': 'bg-blue-100 text-blue-700',
      'in-progress': 'bg-blue-100 text-blue-700',
      'completed': 'bg-green-100 text-green-700',
      'cancelled': 'bg-red-100 text-red-700',
    };
    return styles[status] || 'bg-gray-100 text-gray-700';
  };

  const formatDate = (dateString) => {
    const date = new Date(dateString);
    return date.toLocaleDateString('en-US', { 
      year: 'numeric', 
      month: 'short', 
      day: 'numeric' 
    });
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center h-full">
        <div className="text-gray-700 text-xl">Loading...</div>
      </div>
    );
  }

  return (
    <div className="admin-page">
      {/* Page Title */}
      <div>
        <h1 className="admin-page-title mb-2">Dashboard Overview</h1>
        <p className="admin-page-subtitle">Track your platform's performance and metrics</p>
      </div>

      {/* Stats Cards */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <StatsCard
          title="Total Jobs"
          value={stats.totalJobs}
          icon={Briefcase}
          color="orange"
        />
        <StatsCard
          title="Active Techs"
          value={stats.activeTechnicians}
          icon={Users}
          color="blue"
        />
        <StatsCard
          title="Monthly Revenue"
          value={formatCurrency(stats.monthlyRevenue)}
          icon={DollarSign}
          color="green"
        />
        <StatsCard
          title="Pending"
          value={stats.pendingJobs}
          icon={Clock}
          color="blue"
        />
      </div>

      {/* Revenue Trend Chart */}
      <div className="admin-card-pad">
        <h2 className="admin-section-title mb-6">Revenue Trend</h2>
        
        {/* Simple Chart Placeholder */}
        <div className="h-64 flex items-end justify-around gap-2 px-4">
          {['May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov'].map((month) => {
            const height = Math.random() * 80 + 20; // Random height between 20-100%
            return (
              <div key={month} className="flex-1 flex flex-col items-center gap-2">
                <div className="w-full bg-gradient-to-t from-blue-600 to-cyan-400 rounded-t-lg transition-all hover:from-blue-500 hover:to-cyan-300" 
                     style={{ height: `${height}%` }}>
                </div>
                <span className="text-gray-800 text-sm font-medium">{month}</span>
              </div>
            );
          })}
        </div>
        
        <div className="mt-4 text-center">
          <p className="text-gray-800 text-sm font-medium">Monthly Revenue Trend (Last 7 Months)</p>
        </div>
      </div>

      {/* All Jobs Table */}
      <div className="admin-card-pad">
        <div className="flex items-center justify-between mb-6">
          <h2 className="admin-section-title">All Jobs</h2>
          {recentJobs.length > 0 && (
            <button 
              onClick={() => window.location.href = '/admin/jobs'}
              className="text-blue-600 hover:text-blue-700 text-sm font-medium"
            >
              View All →
            </button>
          )}
        </div>

        {recentJobs.length === 0 ? (
          <div className="text-center py-12">
            <p className="text-gray-800 text-lg mb-4">No jobs found</p>
            <p className="text-gray-700 text-sm">Jobs will appear here once customers book services</p>
          </div>
        ) : (
          <div className="overflow-x-auto">
            <table className="w-full">
              <thead>
                <tr>
                  <th className="admin-table-head text-left py-3 px-4">Customer</th>
                  <th className="admin-table-head text-left py-3 px-4">Service</th>
                  <th className="admin-table-head text-left py-3 px-4">Technician</th>
                  <th className="admin-table-head text-left py-3 px-4">Status</th>
                  <th className="admin-table-head text-left py-3 px-4">Date</th>
                </tr>
              </thead>
              <tbody>
                {recentJobs.map((job) => (
                  <tr key={job.id} className="admin-table-row">
                    <td className="py-4 px-4">
                      <p className="text-gray-800 font-medium">{job.customer?.name || 'N/A'}</p>
                    </td>
                    <td className="py-4 px-4">
                      <p className="text-gray-700">{job.service?.name || 'N/A'}</p>
                    </td>
                    <td className="py-4 px-4">
                      <p className="text-gray-700">{job.technician?.name || 'Not Assigned'}</p>
                    </td>
                    <td className="py-4 px-4">
                      <span className={`admin-chip capitalize ${getStatusBadge(job.status)}`}>
                        {job.status}
                      </span>
                    </td>
                    <td className="py-4 px-4">
                      <p className="text-gray-800 text-sm font-medium">{formatDate(job.createdAt)}</p>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>
    </div>
  );
};

export default Overview;

﻿import { useState, useEffect } from 'react';
import { adminAPI } from '../../services/api';
import { TrendingUp, Calendar, Users } from 'lucide-react';

const Revenue = () => {
  const [revenueData, setRevenueData] = useState({
    totalRevenue: 0,
    monthlyRevenue: [],
    technicianPayouts: []
  });
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchRevenue();
  }, []);

  const fetchRevenue = async () => {
    try {
      const [monthlyRes, paymentsRes] = await Promise.all([
        adminAPI.getMonthlyRevenue(),
        adminAPI.getAllBookings({ status: 'completed' })
      ]);
      
      let totalRevenue = 0;
      const monthlyData = [];
      const technicianEarnings = {};

      if (monthlyRes.data.success) {
        const months = monthlyRes.data.data || [];
        months.forEach(item => {
          const revenue = parseFloat(item.revenue || 0);
          totalRevenue += revenue;
          monthlyData.push({
            month: new Date(item.month).toLocaleString('default', { month: 'long' }),
            revenue
          });
        });
      }

      if (paymentsRes.data.success) {
        const completedJobs = paymentsRes.data.data.bookings || [];
        completedJobs.forEach(job => {
          const jobAmount = 2000;
          const platformFee = jobAmount * 0.05;
          const technicianEarning = jobAmount * 0.95;

          if (job.technician) {
            if (!technicianEarnings[job.technician.id]) {
              technicianEarnings[job.technician.id] = {
                name: job.technician.name,
                totalJobs: 0,
                totalEarnings: 0,
                platformFees: 0
              };
            }
            technicianEarnings[job.technician.id].totalJobs += 1;
            technicianEarnings[job.technician.id].totalEarnings += technicianEarning;
            technicianEarnings[job.technician.id].platformFees += platformFee;
          }
        });
      }

      setRevenueData({
        totalRevenue,
        monthlyRevenue: monthlyData,
        technicianPayouts: Object.values(technicianEarnings)
      });
    } catch (error) {
      console.error('Error fetching revenue:', error);
      setRevenueData({
        totalRevenue: 0,
        monthlyRevenue: [],
        technicianPayouts: []
      });
    } finally {
      setLoading(false);
    }
  };

  const formatCurrency = (amount) => {
    return `रू ${amount.toLocaleString('en-NP', { 
      minimumFractionDigits: 2,
      maximumFractionDigits: 2 
    })}`;
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center h-full">
        <div className="text-gray-700 text-xl">Loading revenue data...</div>
      </div>
    );
  }

  const hasRevenue = revenueData.monthlyRevenue.length > 0;
  const hasPayouts = revenueData.technicianPayouts.length > 0;

  return (
    <div className="admin-page">
      <div>
        <h1 className="admin-page-title mb-2">Revenue Breakdown</h1>
        <p className="admin-page-subtitle">Track platform earnings and financial metrics</p>
      </div>

      {/* Platform Revenue */}
      <div className="admin-card p-6">
        <div className="flex items-center gap-4 mb-2">
          <div className="w-16 h-16 rounded-full bg-gradient-to-br from-green-500 to-emerald-600 flex items-center justify-center text-white text-3xl font-bold">
            रू
          </div>
          <div>
            <p className="text-gray-800 text-sm font-medium">Platform Revenue (5% Commission)</p>
            <h2 className="text-4xl font-bold text-gray-900">
              {formatCurrency(revenueData.totalRevenue)}
            </h2>
          </div>
        </div>

        <div className="mt-4 p-4 bg-blue-50 border border-blue-200 rounded-lg">
          <p className="text-gray-800 text-sm">
            <strong>How it works:</strong> Fixly takes 5% commission from each completed job.
            Technicians receive 95% at month-end via their bank accounts.
          </p>
        </div>
      </div>

      {/* Monthly Revenue */}
      <div className="admin-card-pad">
        <div className="flex items-center gap-2 mb-6">
          <Calendar size={24} className="text-blue-600" />
          <h2 className="admin-section-title">Monthly Platform Earnings (5%)</h2>
        </div>

        {!hasRevenue ? (
          <div className="text-center py-12">
            <TrendingUp size={64} className="mx-auto text-gray-300 mb-4" />
            <p className="text-gray-800 text-lg mb-2">No revenue data yet</p>
            <p className="text-gray-700 text-sm">
              Revenue will be tracked month by month as jobs are completed
            </p>
          </div>
        ) : (
          <div className="space-y-4">
            {revenueData.monthlyRevenue.map((item, index) => (
              <div 
                key={index}
                className="flex items-center justify-between p-4 bg-gray-50 hover:bg-blue-50 rounded-lg border border-gray-200 transition-colors"
              >
                <div className="flex items-center gap-3">
                  <div className="w-12 h-12 rounded-full bg-gradient-to-br from-blue-500 to-cyan-500 flex items-center justify-center text-white font-bold">
                    {item.month.substring(0, 3)}
                  </div>
                  <div>
                    <p className="text-gray-800 font-semibold">{item.month}</p>
                    <p className="text-gray-800 text-sm font-medium">5% platform commission</p>
                  </div>
                </div>
                <div className="text-right">
                  <p className="text-2xl font-bold text-green-700">
                    {formatCurrency(item.revenue)}
                  </p>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>

      {/* Technician Payouts */}
      <div className="admin-card-pad">
        <div className="flex items-center gap-2 mb-6">
          <Users size={24} className="text-blue-600" />
          <h2 className="admin-section-title">Technician Monthly Payouts (95%)</h2>
        </div>

        {!hasPayouts ? (
          <div className="text-center py-12">
            <Users size={64} className="mx-auto text-gray-300 mb-4" />
            <p className="text-gray-800 text-lg mb-2">No payouts yet</p>
            <p className="text-gray-700 text-sm">
              Technician earnings will appear here once jobs are completed
            </p>
          </div>
        ) : (
          <div className="space-y-4">
            {revenueData.technicianPayouts.map((tech, index) => (
              <div 
                key={index}
                className="p-4 bg-gray-50 rounded-lg border border-gray-200"
              >
                <div className="flex items-center justify-between mb-3">
                  <div className="flex items-center gap-3">
                    <div className="w-12 h-12 rounded-full bg-gradient-to-br from-blue-500 to-blue-700 flex items-center justify-center text-white font-bold">
                      {tech.name.charAt(0)}
                    </div>
                    <div>
                      <p className="text-gray-800 font-semibold">{tech.name}</p>
                      <p className="text-gray-800 text-sm font-medium">{tech.totalJobs} completed jobs</p>
                    </div>
                  </div>
                  <div className="text-right">
                    <p className="text-2xl font-bold text-green-700">
                      {formatCurrency(tech.totalEarnings)}
                    </p>
                    <p className="text-gray-700 text-sm">To be transferred</p>
                  </div>
                </div>
                <div className="flex justify-between text-sm">
                  <span className="text-gray-700">Platform Fee (5%):</span>
                  <span className="text-yellow-700 font-medium">
                    {formatCurrency(tech.platformFees)}
                  </span>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>

      {/* Info Card */}
      <div className="admin-card-pad bg-blue-50 border-blue-200">
        <h3 className="text-gray-800 font-bold mb-3">Revenue Example</h3>
        <div className="space-y-2 text-gray-700 text-sm">
          <p>Job Amount: रू 2,000</p>
          <p>Platform Fee (5%): <span className="text-green-700 font-bold">रू 100</span></p>
          <p>Technician Gets (95%): <span className="text-blue-700 font-bold">रू 1,900</span></p>
          <p className="mt-3 pt-3 border-t border-gray-200">
            End of month: रू 1,900 x number of jobs, transferred to technician's bank
          </p>
        </div>
      </div>
    </div>
  );
};

export default Revenue;

﻿import { useMemo, useState } from 'react';
import { Upload, Check, AlertCircle, Lock, User as UserIcon, Mail, Phone, KeyRound } from 'lucide-react';
import { adminAPI } from '../../services/api';
import { getImageUrl } from '../../utils/imageHelper';

const Settings = () => {
  const adminData = useMemo(() => JSON.parse(localStorage.getItem('user') || '{}'), []);

  const [profileData, setProfileData] = useState({
    name: adminData.name || '',
    email: adminData.email || '',
    phone: adminData.phone || '',
  });

  const [passwordData, setPasswordData] = useState({
    currentPassword: '',
    newPassword: '',
    confirmPassword: '',
  });

  const [profileImage, setProfileImage] = useState(null);
  const [imagePreview, setImagePreview] = useState(
    adminData.profile_image ? getImageUrl(adminData.profile_image) : null
  );
  const [profileLoading, setProfileLoading] = useState(false);
  const [passwordLoading, setPasswordLoading] = useState(false);
  const [success, setSuccess] = useState('');
  const [error, setError] = useState('');

  const handleProfileChange = (event) => {
    const { name, value } = event.target;
    setProfileData((previous) => ({
      ...previous,
      [name]: value,
    }));
  };

  const handlePasswordChange = (event) => {
    const { name, value } = event.target;
    setPasswordData((previous) => ({
      ...previous,
      [name]: value,
    }));
  };

  const handleImageChange = (event) => {
    const file = event.target.files?.[0];
    if (!file) return;

    if (!file.type.startsWith('image/')) {
      setError('Please select a valid image file.');
      return;
    }

    if (file.size > 5 * 1024 * 1024) {
      setError('Image size should be less than 5MB.');
      return;
    }

    setError('');
    setProfileImage(file);

    const reader = new FileReader();
    reader.onloadend = () => setImagePreview(reader.result);
    reader.readAsDataURL(file);
  };

  const handleProfileSubmit = async (event) => {
    event.preventDefault();
    setProfileLoading(true);
    setError('');
    setSuccess('');

    try {
      const submitData = new FormData();
      submitData.append('name', profileData.name);
      submitData.append('email', profileData.email);
      submitData.append('phone', profileData.phone);

      if (profileImage) {
        submitData.append('profile_image', profileImage);
      }

      const response = await adminAPI.updateProfile(submitData);
      if (response.data?.success) {
        const updatedUser = response.data.data;
        localStorage.setItem('user', JSON.stringify(updatedUser));
        // Don't show success toast - notification will appear in dropdown instead
        setProfileImage(null);
      }
    } catch (requestError) {
      setError(requestError.response?.data?.message || 'Failed to update profile.');
    } finally {
      setProfileLoading(false);
    }
  };

  const handlePasswordSubmit = async (event) => {
    event.preventDefault();
    setPasswordLoading(true);
    setError('');
    setSuccess('');

    if (passwordData.newPassword !== passwordData.confirmPassword) {
      setError('New password and confirm password do not match.');
      setPasswordLoading(false);
      return;
    }

    if (passwordData.newPassword.length < 6) {
      setError('New password must be at least 6 characters.');
      setPasswordLoading(false);
      return;
    }

    try {
      const response = await adminAPI.changePassword({
        currentPassword: passwordData.currentPassword,
        newPassword: passwordData.newPassword,
      });

      if (response.data?.success) {
        // Don't show success toast - notification will appear in dropdown instead
        setPasswordData({
          currentPassword: '',
          newPassword: '',
          confirmPassword: '',
        });
      }
    } catch (requestError) {
      setError(requestError.response?.data?.message || 'Failed to change password.');
    } finally {
      setPasswordLoading(false);
    }
  };

  return (
    <div className="mx-auto w-full max-w-6xl admin-page">
      <div className="admin-card px-6 py-5">
        <h1 className="admin-page-title">Settings</h1>
        <p className="admin-page-subtitle mt-1 text-sm">Manage your profile information and account security.</p>
      </div>

      {success && (
        <div className="rounded-xl border border-green-200 bg-green-50 px-4 py-3 flex items-center gap-3">
          <Check className="text-green-600" size={20} />
          <p className="text-green-700 text-sm">{success}</p>
        </div>
      )}

      {error && (
        <div className="rounded-xl border border-red-200 bg-red-50 px-4 py-3 flex items-center gap-3">
          <AlertCircle className="text-red-600" size={20} />
          <p className="text-red-700 text-sm">{error}</p>
        </div>
      )}

      <section id="profile" className="admin-card-pad">
        <div className="mb-6 flex items-center gap-3">
          <div className="rounded-lg bg-blue-500/20 p-2">
            <UserIcon size={20} className="text-blue-700" />
          </div>
          <div>
            <h2 className="admin-section-title">Profile</h2>
            <p className="text-sm text-gray-800">Update your name, contact details, and profile image.</p>
          </div>
        </div>

        <form onSubmit={handleProfileSubmit} className="space-y-6">
          <div className="flex flex-col gap-4 sm:flex-row sm:items-center">
            <div className="h-24 w-24 rounded-full bg-gradient-to-br from-blue-600 to-cyan-500 flex items-center justify-center overflow-hidden">
              {imagePreview ? (
                <img src={imagePreview} alt="Admin profile" className="h-full w-full object-cover" />
              ) : (
                <span className="text-2xl font-bold text-white">{(profileData.name || 'A').charAt(0).toUpperCase()}</span>
              )}
            </div>

            <div>
              <label className="inline-flex cursor-pointer items-center gap-2 rounded-lg bg-blue-600 px-4 py-2 text-sm font-medium text-white hover:bg-blue-500 transition-colors">
                <Upload size={16} />
                Upload picture
                <input type="file" accept="image/*" onChange={handleImageChange} className="hidden" />
              </label>
              <p className="mt-2 text-sm text-gray-700">PNG, JPG, GIF up to 5MB.</p>
            </div>
          </div>

          <div className="grid grid-cols-1 gap-4 md:grid-cols-2">
            <div>
              <label className="mb-2 flex items-center gap-2 text-sm font-medium text-gray-700">
                <UserIcon size={14} className="text-blue-600" />
                Full Name
              </label>
              <input
                type="text"
                name="name"
                value={profileData.name}
                onChange={handleProfileChange}
                required
                className="w-full rounded-lg border border-gray-300 bg-white px-3 py-2 text-gray-800 placeholder:text-gray-500 focus:border-blue-500 focus:outline-none"
              />
            </div>

            <div>
              <label className="mb-2 flex items-center gap-2 text-sm font-medium text-gray-700">
                <Mail size={14} className="text-blue-600" />
                Email
              </label>
              <input
                type="email"
                name="email"
                value={profileData.email}
                onChange={handleProfileChange}
                required
                className="w-full rounded-lg border border-gray-300 bg-white px-3 py-2 text-gray-800 placeholder:text-gray-500 focus:border-blue-500 focus:outline-none"
              />
            </div>

            <div className="md:col-span-2">
              <label className="mb-2 flex items-center gap-2 text-sm font-medium text-gray-700">
                <Phone size={14} className="text-blue-600" />
                Phone Number
              </label>
              <input
                type="tel"
                name="phone"
                value={profileData.phone}
                onChange={handleProfileChange}
                className="w-full rounded-lg border border-gray-300 bg-white px-3 py-2 text-gray-800 placeholder:text-gray-500 focus:border-blue-500 focus:outline-none"
              />
            </div>
          </div>

          <button
            type="submit"
            disabled={profileLoading}
            className="rounded-lg bg-blue-600 hover:bg-blue-700 px-6 py-2.5 text-sm font-semibold text-white transition-colors disabled:cursor-not-allowed disabled:opacity-60"
          >
            {profileLoading ? 'Saving...' : 'Save Profile'}
          </button>
        </form>
      </section>

      <section className="admin-card-pad">
        <div className="mb-6 flex items-center gap-3">
          <div className="rounded-lg bg-amber-500/20 p-2">
            <Lock size={20} className="text-amber-700" />
          </div>
          <div>
            <h2 className="admin-section-title">Change Password</h2>
            <p className="text-sm text-gray-800">Use a strong password with at least 6 characters.</p>
          </div>
        </div>

        <form onSubmit={handlePasswordSubmit} className="space-y-4 max-w-2xl">
          <div>
            <label className="mb-2 flex items-center gap-2 text-sm font-medium text-gray-700">
              <KeyRound size={14} className="text-blue-600" />
              Current Password
            </label>
            <input
              type="password"
              name="currentPassword"
              value={passwordData.currentPassword}
              onChange={handlePasswordChange}
              required
              className="w-full rounded-lg border border-gray-300 bg-white px-3 py-2 text-gray-800 placeholder:text-gray-500 focus:border-blue-500 focus:outline-none"
            />
          </div>

          <div>
            <label className="mb-2 flex items-center gap-2 text-sm font-medium text-gray-700">
              <KeyRound size={14} className="text-blue-600" />
              New Password
            </label>
            <input
              type="password"
              name="newPassword"
              value={passwordData.newPassword}
              onChange={handlePasswordChange}
              minLength={6}
              required
              className="w-full rounded-lg border border-gray-300 bg-white px-3 py-2 text-gray-800 placeholder:text-gray-500 focus:border-blue-500 focus:outline-none"
            />
          </div>

          <div>
            <label className="mb-2 flex items-center gap-2 text-sm font-medium text-gray-700">
              <KeyRound size={14} className="text-blue-600" />
              Confirm New Password
            </label>
            <input
              type="password"
              name="confirmPassword"
              value={passwordData.confirmPassword}
              onChange={handlePasswordChange}
              minLength={6}
              required
              className="w-full rounded-lg border border-gray-300 bg-white px-3 py-2 text-gray-800 placeholder:text-gray-500 focus:border-blue-500 focus:outline-none"
            />
          </div>

          <button
            type="submit"
            disabled={passwordLoading}
            className="rounded-lg bg-blue-600 hover:bg-blue-700 px-6 py-2.5 text-sm font-semibold text-white transition-colors disabled:cursor-not-allowed disabled:opacity-60"
          >
            {passwordLoading ? 'Updating...' : 'Change Password'}
          </button>
        </form>
