    else if (lowerName.includes('carpen') || lowerName.includes('wood')) { Icon = Hammer; colorClass = "bg-orange-100"; }
    else if (lowerName.includes('paint')) { Icon = PaintRoller; colorClass = "bg-pink-100"; }
